const bnField={title:'শিরোনাম',slug:'স্লাগ',description:'বিবরণ',detailed_information:'বিস্তারিত তথ্য',routine:'রুটিন',price:'মূল্য',sale_price:'ছাড়ের পর মূল্য',status:'অবস্থা',course_id:'কোর্স আইডি',name:'নাম',batch_code:'ব্যাচ কোড',start_date:'শুরুর তারিখ',end_date:'শেষের তারিখ',enrollment_start:'ভর্তি শুরুর সময়',enrollment_end:'ভর্তি শেষের সময়',capacity:'আসনসংখ্যা',subject_id:'বিষয় আইডি',chapter_id:'অধ্যায় আইডি',question_type:'প্রশ্নের ধরন',question_text:'প্রশ্ন',correct_answer_text:'সঠিক উত্তর',explanation:'ব্যাখ্যা',difficulty:'কঠিনতার মাত্রা',default_marks:'নির্ধারিত নম্বর',default_negative_marks:'নির্ধারিত নেগেটিভ নম্বর',is_active:'সক্রিয়',question_id:'প্রশ্ন আইডি',option_label:'অপশন লেবেল',option_text:'অপশনের লেখা',option_image_path:'অপশনের ছবির ঠিকানা',is_correct:'সঠিক উত্তর কি না',display_order:'প্রদর্শনের ক্রম',storage_path:'স্টোরেজ ঠিকানা',alt_text:'বিকল্প বর্ণনা',batch_id:'ব্যাচ আইডি',exam_type:'পরীক্ষার ধরন',instructions:'নির্দেশনা',start_time:'শুরুর সময়',end_time:'শেষের সময়',duration_minutes:'সময়কাল (মিনিট)',total_marks:'মোট নম্বর',randomize_questions:'প্রশ্ন এলোমেলোভাবে দেখান',randomize_options:'অপশন এলোমেলোভাবে দেখান',warn_on_tab_switch:'ট্যাব পরিবর্তনে সতর্ক করুন',log_tab_switches:'ট্যাব পরিবর্তনের তথ্য রাখুন',require_fullscreen:'ফুলস্ক্রিন বাধ্যতামূলক',prevent_copy_paste:'কপি-পেস্ট বন্ধ রাখুন',device_limit:'ডিভাইস সীমা',allow_resume:'পুনরায় পরীক্ষা চালুর অনুমতি',max_attempts:'সর্বোচ্চ প্রচেষ্টা',show_results:'ফলাফল দেখান',show_correct_answers:'সঠিক উত্তর দেখান',exam_question_id:'পরীক্ষার প্রশ্ন আইডি',criteria:'মূল্যায়নের মানদণ্ড',max_marks:'সর্বোচ্চ নম্বর',subtitle:'সাবটাইটেল',image_path:'ছবির ঠিকানা',target_url:'লক্ষ্য লিংক',starts_at:'শুরুর সময়',expires_at:'মেয়াদ শেষ',message:'বার্তা',announcement_type:'ঘোষণার ধরন',is_published:'প্রকাশিত',publish_at:'প্রকাশের সময়',code:'কোড',discount_type:'ছাড়ের ধরন',discount_value:'ছাড়ের পরিমাণ',max_discount:'সর্বোচ্চ ছাড়',min_purchase:'সর্বনিম্ন ক্রয়',usage_limit:'ব্যবহারের সীমা',per_user_limit:'প্রতি ব্যবহারকারীর সীমা',setting_key:'সেটিংস কী',setting_value:'সেটিংসের মান',is_published:'প্রকাশিত'};
function translateUI(root=document.getElementById('app')){
  if(!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){const raw=node.nodeValue,trim=raw.trim();if(!trim)continue;let translated=bnUI[trim];
    if(!translated){const key=trim.toLowerCase();translated=bnField[key.replaceAll(' ','_')]||bnUI[key];}
    if(!translated){let m=trim.match(/^Good (morning|afternoon|evening),\s*(.*)$/);if(m)translated=({morning:'সুপ্রভাত',afternoon:'শুভ অপরাহ্ণ',evening:'শুভ সন্ধ্যা'}[m[1]])+', '+m[2];}
    if(!translated){let m=trim.match(/^QUESTION (\d+) OF (\d+) · (.+)$/);if(m)translated=`প্রশ্ন ${m[1]} / ${m[2]} · ${m[3]==='MCQ'?'MCQ':m[3]}`;}
    if(!translated){let m=trim.match(/^QUESTION (\d+) · (.+)$/);if(m)translated=`প্রশ্ন ${m[1]} · ${m[2]}`;}
    if(!translated){let m=trim.match(/^(.*?) — Question preview$/);if(m)translated=`${m[1]} — প্রশ্নের প্রিভিউ`;}
    if(!translated){let m=trim.match(/^(\d+) questions · (.+) total marks$/);if(m)translated=`${m[1]}টি প্রশ্ন · মোট নম্বর ${m[2]}`;}
    if(!translated){let m=trim.match(/^(Add|Edit) (.+)$/);if(m)translated=`${m[1]==='Add'?'যোগ করুন':'সম্পাদনা করুন'} ${bnField[m[2].replaceAll(' ','_')]||bnUI[m[2]]||m[2]}`;}
    if(!translated){let m=trim.match(/^ADMIN ACCESS · (.+)$/);if(m)translated=`অ্যাডমিন প্রবেশাধিকার · ${m[1]}`;}
    if(!translated){let m=trim.match(/^(\d+) total$/);if(m)translated=`মোট ${m[1]}টি`;}
    if(!translated){let m=trim.match(/^No (.+) found\.$/);if(m){const k=m[1].toLowerCase().replaceAll(' ','_');translated=`কোনো ${bnField[k]||bnUI[m[1]]||m[1]} পাওয়া যায়নি।`;}}
    if(!translated){let m=trim.match(/^Are you sure you want to (publish|unpublish) this course\?$/);if(m)translated=m[1]==='publish'?'আপনি কি কোর্সটি প্রকাশ করতে চান?':'আপনি কি কোর্সটির প্রকাশনা বন্ধ করতে চান?';}
    if(!translated){let m=trim.match(/^Question (\d+): (.+)$/);if(m)translated=`প্রশ্ন ${m[1]}: ${m[2]==='question_text is required.'?'প্রশ্নের লেখা দিতে হবে।':m[2]}`;}
    if(translated!==undefined&&translated!==trim)node.nodeValue=raw.replace(trim,translated);
  }
  for(const el of root.querySelectorAll('[placeholder],[title],[alt],[aria-label]'))for(const attr of ['placeholder','title','alt','aria-label']){const v=el.getAttribute(attr);if(v&&bnUI[v])el.setAttribute(attr,bnUI[v]);}
}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`${C.CURRENCY||'৳'}${Number(n||0).toLocaleString('en-BD')}`;
const date=s=>s?new Date(s).toLocaleString('en-BD',{dateStyle:'medium',timeStyle:'short'}):'—';
const status=s=>{const v=(s||'unknown').replaceAll('_',' ');const bn={active:'সক্রিয়',paid:'পরিশোধিত',published:'প্রকাশিত',approved:'অনুমোদিত',pending:'অপেক্ষমাণ',draft:'খসড়া',in_progress:'চলমান',failed:'ব্যর্থ',cancelled:'বাতিল',rejected:'প্রত্যাখ্যাত',submitted:'জমা হয়েছে',evaluated:'মূল্যায়িত',auto_submitted:'স্বয়ংক্রিয়ভাবে জমা',unknown:'অজানা'};return `<span class="status ${esc(s)}">${esc(bn[s]||bn[v]||v)}</span>`};
const toast=(m,err=false)=>{let n=document.createElement('div');n.className='toast'+(err?' error':'');const msg=String(m);n.textContent=bnUI[msg]||msg.replace(/^Exam created with (\d+) questions\.$/,'$1টি প্রশ্নসহ পরীক্ষা তৈরি হয়েছে।');$('#toast-root').append(n);setTimeout(()=>n.remove(),3500)};
const err=e=>{console.error(e);toast(e?.message||'Something went wrong. Please try again.',true)};
/* ---- Rich notifications ---- */
const NOTE_ICONS={success:'✓',info:'ℹ',pending:'⏳',error:'!'};
function notify(type,title,message,ms=5000){let root=$('#toast-root');if(!root)return;let n=document.createElement('div');n.className='note note-'+type;n.setAttribute('role','status');n.innerHTML=`<span class="note-ico">${NOTE_ICONS[type]||'ℹ'}</span><div class="note-body"><strong>${esc(title)}</strong>${message?`<p>${esc(message)}</p>`:''}</div><button class="note-x" aria-label="Close">×</button><i class="note-bar" style="animation-duration:${ms}ms"></i>`;let kill=()=>{n.classList.add('out');setTimeout(()=>n.remove(),250)};$('.note-x',n).onclick=kill;root.append(n);setTimeout(kill,ms)}
function statusModal({icon='✓',tone='success',title,message,steps=[],button='ঠিক আছে',onClose}){$('#status-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="status-modal"><div class="modal status-modal ${tone}" role="dialog" aria-modal="true"><div class="status-ico">${icon}</div><h2>${esc(title)}</h2><p class="status-msg">${esc(message)}</p>${steps.length?`<ol class="status-steps">${steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`:''}<div class="modal-actions" style="justify-content:center"><button class="btn btn-primary" id="status-ok">${esc(button)}</button></div></div></div>`);let close=()=>{$('#status-modal')?.remove();onClose&&onClose()};$('#status-ok').onclick=close;$('#status-modal').addEventListener('click',e=>{if(e.target.id==='status-modal')close()})}
function loginOverlay(show,text='আপনাকে লগইন করানো হচ্ছে…'){$('#login-overlay')?.remove();if(show)document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="login-overlay"><div class="login-box"><div class="spinner"></div><strong>${esc(text)}</strong><small>অনুগ্রহ করে অপেক্ষা করুন</small></div></div>`)}
const result=async q=>{const {data,error}=await q;if(error)throw error;return data};
const rpc=async(name,args={})=>result(sb.rpc(name,args));
const asset=(name)=>C.ASSET_PATHS?.[name]||'';
const picture=(p)=>p?sb.storage.from('profile-pictures').getPublicUrl(p).data.publicUrl:'';
function setTheme(t){document.documentElement.dataset.theme=t;localStorage.setItem('admirank-theme',t);$$('[data-theme-toggle]').forEach(b=>b.textContent=t==='dark'?'☀ লাইট মোড':'☾ ডার্ক মোড')}
function themeButton(){return `<button class="theme-toggle" data-theme-toggle type="button">${(localStorage.getItem('admirank-theme')||'dark')==='dark'?'☀ লাইট মোড':'☾ ডার্ক মোড'}</button>`}
setTheme(localStorage.getItem('admirank-theme')||'dark');
const logo=()=>`<img src="${esc(asset('logo'))}" onerror="this.style.display='none'" alt="AdmiRank">`;
