function courseCard(c){return `<article class="course-card"><div class="course-cover">${c.thumbnail_path?`<img src="${esc(publicAsset(c.thumbnail_path))}" alt="">`:`<img src="${esc(asset('coursePoster'))}" onerror="this.outerHTML='<div style=&quot;font-size:58px&quot;>🎓</div>'" alt="">`}</div><div class="course-content"><span class="tag">ADMISSION PREPARATION</span><h3>${esc(c.title)}</h3><p>${esc(c.description||'A structured course to support your admission preparation.')}</p><div class="price">${money(c.sale_price??c.price)} ${c.sale_price&&c.price?`<del>${money(c.price)}</del>`:''}</div><a class="btn btn-primary" style="width:100%;margin-top:16px" href="#course/${encodeURIComponent(c.id)}">View course →</a></div></article>`}
function publicAsset(path){return sb.storage.from('public-assets').getPublicUrl(path).data.publicUrl}
function noticeCard(n){return `<article class="notice-card"><span class="tag">${esc(n.announcement_type||'notice')}</span><h3>${esc(n.title)}</h3><p>${esc(n.message)}</p><small class="muted">${date(n.publish_at||n.created_at)}</small></article>`}
async function coursesPage(){let cs=await publicData('courses').then(x=>x.filter(c=>c.status==='published')).catch(()=>[]);return `${topbar()}<section class="section"><div class="eyebrow">Our programs</div><h2>Admission preparation courses</h2><p class="section-sub">Explore available courses and their published batches.</p><div class="grid" style="margin-top:28px">${cs.length?cs.map(courseCard).join(''):'<div class="empty" style="grid-column:1/-1">No published courses are available right now.</div>'}</div></section>${footer()}`}
async function courseDetail(slug){
  const key=decodeURIComponent(slug||'');
  const isAdmin=state.roles.includes('admin');
  let c=await result(sb.from('courses').select('*').eq('id',key).maybeSingle()).catch(()=>null);
  if(!c)c=await result(sb.from('courses').select('*').eq('slug',key).maybeSingle()).catch(()=>null);
  if(!c)c=await result(sb.from('courses').select('*').eq('title',key).maybeSingle()).catch(()=>null);
  if(!c)return `${topbar()}<section class="section"><h2>Course not found</h2><p class="muted">This course may be unpublished or its link may have changed.</p><a href="#courses">Back to courses</a></section>${footer()}`;
  const bs=await publicData('batches').then(x=>x.filter(b=>b.course_id===c.id&&(isAdmin||['published','ongoing'].includes(b.status)))).catch(()=>[]);
  const batchIds=bs.map(b=>b.id);
  const exams=batchIds.length?await result(sb.from('exams').select('id,title,start_time,end_time,duration_minutes,batch_id,status').in('batch_id',batchIds).order('start_time')).then(rows=>rows.filter(e=>isAdmin||e.status==='published')).catch(()=>[]):[];
  const routine=c.routine||c.exam_routine||'';
  return `${topbar()}<section class="section"><a href="#courses" class="muted">← All courses</a><div class="grid" style="grid-template-columns:1.2fr .8fr;margin-top:25px"><div><span class="tag">ADMISSION COURSE</span><h1 style="font:800 38px Manrope">${esc(c.title)}</h1><p class="section-sub">${esc(c.description||'')}</p>${c.detailed_information?`<section class="course-extra"><h2>Course details</h2><div class="rich-text">${esc(c.detailed_information).replaceAll('\n','<br>')}</div></section>`:''}${routine?`<section class="course-extra"><h2>Class & exam routine</h2><div class="rich-text">${esc(routine).replaceAll('\n','<br>')}</div></section>`:''}<section class="course-extra"><h2>Exam routine</h2>${exams.length?`<div class="table-wrap"><table><thead><tr><th>Examination</th><th>Date & time</th><th>Duration</th></tr></thead><tbody>${exams.map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${date(e.start_time)} – ${examEndText(e)}</td><td>${e.duration_minutes||'—'} min</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">The exam routine will be published here when examinations are scheduled.</p>'}</section><h3>Available batches</h3>${bs.length?bs.map(b=>`<div class="notice-card"><strong>${esc(b.name)}</strong> · ${esc(b.batch_code||'')}<p>${esc(b.description||'')}<br>${date(b.start_date)} – ${date(b.end_date)}</p><button class="btn btn-primary btn-sm" onclick="window.enroll('${b.id}')">Enroll in batch</button></div>`).join(''):'<p class="muted">No published batches are available yet.</p>'}</div><div class="course-card"><div class="course-cover"><img src="${esc(c.thumbnail_path?publicAsset(c.thumbnail_path):asset('coursePoster'))}" onerror="this.style.display='none'"></div><div class="course-content"><h3>${esc(c.title)}</h3><div class="price">${money(c.sale_price??c.price)}</div>${bs.length?`<button class="btn btn-primary" style="width:100%;margin-top:18px" onclick="window.enroll('${bs[0].id}')">Enroll now</button>`:'<p class="muted">Enrollment is not open yet.</p>'}</div></div></div></section>${footer()}`
}

async function noticesPage(){let ns=await publicData('announcements').catch(()=>[]);return `${topbar()}<section class="section"><div class="eyebrow">Updates</div><h2>Announcements & notices</h2><div style="margin-top:25px">${ns.length?ns.map(noticeCard).join(''):'<div class="empty">There are no published announcements.</div>'}</div></section>${footer()}`}
function authPage(kind){let title={login:'Welcome back',register:'Create your account',forgot:'Reset your password'}[kind];return `<div class="auth-wrap"><aside class="auth-side"><a class="brand" href="#home" style="color:white">${logo()}<span>AdmiRank</span></a><h1>${kind==='register'?'Your next chapter starts here.':'Your admission goals are worth preparing for.'}</h1><p>Join a focused learning environment with model tests, performance tracking and structured admission preparation.</p><a href="#home" style="margin-top:35px;color:#cbd6ed">← Back to website</a></aside><main class="auth-main"><form class="auth-box" id="auth-form"><div style="display:flex;justify-content:flex-end">${themeButton()}</div><a class="brand" href="#home">${logo()}<span>AdmiRank</span></a><h2 style="margin-top:28px">${title}</h2><p>${kind==='login'?'Log in to continue your preparation.':kind==='register'?'Register to access your student dashboard.':'We will email you a password reset link.'}</p>${kind==='register'?`<div class="field"><label>Full name</label><input name="full_name" required placeholder="Enter your full name"></div><div class="field"><label>Phone number</label><input name="phone" placeholder="Enter your phone number"></div>`:''}<div class="field"><label>Email address</label><input type="email" name="email" required placeholder="you@example.com"></div>${kind!=='forgot'?`<div class="field"><label>Password</label><input type="password" name="password" required minlength="6" placeholder="Enter your password"></div>`:''}${kind==='login'?`<div class="auth-links"><a href="#forgot">Forgot password?</a><a href="#register">Create account</a></div>`:kind==='register'?`<div class="auth-links"><span>By registering, you agree to use the platform responsibly.</span><a href="#login">Log in</a></div>`:`<div class="auth-links"><a href="#login">Back to login</a></div>`}<button class="btn btn-primary" type="submit">${kind==='login'?'Log in':kind==='register'?'Create account':'Send reset link'} →</button><div class="divider-text">Secure authentication by Supabase</div></form></main></div>`}
async function submitAuth(form,kind){let fd=new FormData(form),email=fd.get('email'),password=fd.get('password');if(kind==='register'){let {data,error}=await sb.auth.signUp({email,password,options:{data:{full_name:fd.get('full_name'),phone:fd.get('phone')}}});if(error)throw error;notify(data.session?'success':'info',data.session?'অ্যাকাউন্ট তৈরি হয়েছে':'ইমেইল যাচাই করুন',data.session?'আপনার অ্যাকাউন্ট সফলভাবে তৈরি হয়েছে।':'আপনার ইমেইলে একটি কনফার্মেশন লিংক পাঠানো হয়েছে।',6000);if(data.session)await loadUser();else go('login')}else if(kind==='login'){loginOverlay(true);try{let {error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;await loadUser();go('dashboard');let nm=(state.profile?.full_name||state.user?.user_metadata?.full_name||'').trim();notify('success','সফলভাবে লগইন হয়েছে',nm?`স্বাগতম, ${nm}!`:'আপনার অ্যাকাউন্টে স্বাগতম!',4000)}finally{loginOverlay(false)}}else{let {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#reset'});if(error)throw error;toast('Password reset link sent. Check your email.');go('login')}}
async function loadUser(){let {data:{user}}=await sb.auth.getUser();state.user=user;state.profile=null;state.roles=[];if(user){state.profile=await result(sb.from('profiles').select('*').eq('id',user.id).maybeSingle()).catch(()=>null);state.roles=await result(sb.from('user_roles').select('role').eq('user_id',user.id)).then(x=>x.map(r=>r.role)).catch(()=>[])}}
function shell(content,active='dashboard'){let admin=state.roles.includes('admin'),evalr=state.roles.includes('evaluator');return `<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard" style="color:#fff">${logo()}<span>AdmiRank</span></a><div class="side-label">WORKSPACE</div>${navLink('dashboard','Overview','⌂')}${navLink('my-courses','My courses','▣')}${navLink('my-exams','Examinations','✎')}${navLink('results','Results','▤')}${navLink('leaderboard','Leaderboard','♜')}${navLink('profile','My profile','◉')}${admin?`<div class="side-label">ADMINISTRATION</div>${navLink('admin','Admin overview','▦')}${navLink('admin-courses','Courses & batches','▣')}${navLink('admin-payments','Payment verification','৳')}${navLink('admin-questions','Question bank','✎')}${navLink('admin-exams','Exam management','▤')}${navLink('admin-users','Users & assignments','♙')}${navLink('admin-content','Website content','◈')}${navLink('admin-results','Evaluation & results','✓')}`:''}${evalr?`<div class="side-label">EVALUATOR</div>${navLink('evaluator','Assigned scripts','✍')}`:''}<div class="sidebar-bottom"><a class="side-link" href="#home">↗ View website</a><a class="side-link" href="#" id="logout">⇥ Log out</a></div></aside><main class="main-area"><header class="dash-top"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn mobile-menu" id="menu" aria-label="Menu"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h10"/></svg></button><div class="top-title"><strong>${String(state.page).startsWith('admin')?'অ্যাডমিন প্যানেল':'শিক্ষার্থী ড্যাশবোর্ড'}</strong>${state.batchNames?.length?`<div class="top-batches">${state.batchNames.map(n=>`<span>${esc(n)}</span>`).join()}</div>`:''}</div></div><div class="right">${themeButton()}<span class="user-label muted">${esc(state.profile?.full_name||state.user?.email||'Account')}</span><div class="avatar">${state.profile?.profile_picture_path?`<img src="${esc(picture(state.profile.profile_picture_path))}" alt="Profile">`:esc((state.profile?.full_name||state.user?.email||'A').slice(0,1).toUpperCase())}</div></div></header><div class="dash-content">${content}</div></main></div>`}
const EXAM_DATES={A:'2026-12-12T00:00:00+06:00',B:'2026-12-19T00:00:00+06:00'};
function unitOfCourse(t){t=String(t||'');if(/\bDU\s*[-–]?\s*A\b|\bA\s*unit\b|ক\s*ইউনিট/i.test(t))return 'A';if(/\bDU\s*[-–]?\s*B\b|\bB\s*unit\b|খ\s*ইউনিট/i.test(t))return 'B';return null}
let countdownTimer;
function startCountdown(){clearInterval(countdownTimer);const el=$('#unit-countdown');if(!el)return;const target=new Date(el.dataset.target).getTime();const tick=()=>{let box=$('#unit-countdown');if(!box){clearInterval(countdownTimer);return}let d=target-Date.now();if(d<=0){$('.cd-grid',box).innerHTML='<div class="cd-done">ভর্তি পরীক্ষার দিন এসে গেছে — শুভকামনা!</div>';clearInterval(countdownTimer);return}let sec=Math.floor(d/1000),dd=Math.floor(sec/86400),hh=Math.floor(sec%86400/3600),mm=Math.floor(sec%3600/60),ss=sec%60,set=(k,v)=>{let e=$('[data-cd="'+k+'"]',box);if(e)e.textContent=String(v).padStart(2,'0')};set('d',dd);set('h',hh);set('m',mm);set('s',ss)};tick();countdownTimer=setInterval(tick,1000)}
window.toggleOldExams=btn=>{let open=btn.dataset.open!=='1';$$('.old-extra').forEach(r=>r.hidden=!open);btn.dataset.open=open?'1':'0';btn.textContent=open?'কম দেখুন':'সব দেখুন'};
async function dashboard(){let [ens,attempts,results]=await Promise.all([publicData('enrollments').catch(()=>[]),publicData('exam_attempts').catch(()=>[]),publicData('exam_results').catch(()=>[])]);let live=ens.filter(e=>e.status==='active');let use=live.length?live:ens.filter(e=>!['cancelled','rejected','expired'].includes(e.status));let bIds=[...new Set(use.map(e=>e.batch_id))];let batchRows=bIds.length?await result(sb.from('batches').select('id,name,course_id').in('id',bIds)).catch(()=>[]):[];let courseRows=batchRows.length?await result(sb.from('courses').select('id,title').in('id',[...new Set(batchRows.map(b=>b.course_id))])).catch(()=>[]):[];let units=[...new Set(batchRows.map(b=>unitOfCourse(courseRows.find(c=>c.id===b.course_id)?.title)||unitOfCourse(b.name)).filter(Boolean))];let nowIso=new Date().toISOString();let exams=await result(sb.from('exams').select('id,title,start_time,end_time,duration_minutes,status,batch_id').eq('status','published').order('start_time',{ascending:false}).limit(300)).catch(()=>[]);let upcoming=exams.filter(e=>e.end_time>=nowIso).sort((x,y)=>new Date(x.start_time)-new Date(y.start_time));let previous=exams.filter(e=>e.end_time<nowIso);let doneIds=new Set(attempts.map(a=>a.exam_id)),resIds=new Set(results.map(r=>r.exam_id));let attemptedCount=doneIds.size||attempts.length;let countdown=units.map(u=>`<section class="countdown-card" id="unit-countdown" data-target="${EXAM_DATES[u]}"><div class="cd-head"><span class="cd-label">DU ${u==='A'?'ক':'খ'} ইউনিট ভর্তি পরীক্ষা</span><strong>${u==='A'?'১২ ডিসেম্বর':'১৯ ডিসেম্বর'}, ২০২৬</strong></div><div class="cd-grid"><div><b data-cd="d">--</b><small>দিন</small></div><div><b data-cd="h">--</b><small>ঘণ্টা</small></div><div><b data-cd="m">--</b><small>মিনিট</small></div><div><b data-cd="s">--</b><small>সেকেন্ড</small></div></div></section>`).join('');state.batchNames=batchRows.map(b=>b.name);let prevRow=(e,i)=>`<tr class="${i>=5?'old-extra':''}" ${i>=5?'hidden':''}><td><strong>${esc(e.title)}</strong></td><td>${date(e.start_time)}</td><td>${e.duration_minutes} min</td><td>${resIds.has(e.id)?'<a class="btn btn-outline btn-sm" href="#results">ফলাফল দেখুন</a>':doneIds.has(e.id)?'<span class="status pending">ফলাফল অপেক্ষমাণ</span>':'<span class="status">অংশ নেননি</span>'}</td></tr>`;return shell(`${countdown}<div class="stat-grid stat-grid-3"><div class="stat-card"><div class="stat-label">অংশ নেওয়া পরীক্ষা</div><strong>${attemptedCount}</strong></div><div class="stat-card"><div class="stat-label">প্রকাশিত ফলাফল</div><strong>${results.length}</strong></div><div class="stat-card"><div class="stat-label">শিক্ষার্থীর আইডি</div><strong style="font-size:20px">${esc(state.profile?.student_id||'Pending')}</strong></div></div><section class="panel"><div class="panel-head"><h3>Upcoming Exams</h3><a href="#my-exams" class="muted">সব পরীক্ষা →</a></div>${upcoming.length?`<div class="table-wrap"><table><thead><tr><th>Examination</th><th>Starts</th><th>Duration</th><th></th></tr></thead><tbody>${upcoming.map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${date(e.start_time)}</td><td>${e.duration_minutes} min</td><td><a class="btn btn-primary btn-sm" href="#exam-info/${e.id}">Open</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No upcoming exams found.</div>'}</section><section class="panel"><div class="panel-head"><h3>Previous Exams</h3>${previous.length>5?'<button class="btn btn-outline btn-sm" data-open="0" onclick="toggleOldExams(this)">সব দেখুন</button>':''}</div>${previous.length?`<div class="table-wrap"><table><thead><tr><th>Examination</th><th>Date</th><th>Duration</th><th></th></tr></thead><tbody>${previous.map(prevRow).join('')}</tbody></table></div>`:'<div class="empty">No previous exams yet.</div>'}</section>`)}
async function myCourses(){
  const isAdmin=state.roles.includes('admin');
  if(isAdmin){
    const courses=await publicData('courses').catch(()=>[]);
    const batches=await publicData('batches').catch(()=>[]);
    return shell(`<div class="page-title"><div><h1>My courses</h1><p>As an administrator, you have access to every course and batch.</p></div><a href="#admin-courses" class="btn btn-outline">Manage courses</a></div><div class="grid">${courses.length?courses.map(c=>{const own=batches.filter(b=>b.course_id===c.id);return `<article class="course-card"><div class="course-content"><span class="tag">ADMIN ACCESS · ${esc(c.status||'')}</span><h3>${esc(c.title)}</h3><p>${esc(c.description||'')}</p><p>${own.length} batch(es) · ${own.map(b=>esc(b.name)).join(', ')||'No batch created yet'}</p><a class="btn btn-primary" href="#course/${encodeURIComponent(c.id)}">View course →</a></div></article>`}).join(''):'<div class="empty" style="grid-column:1/-1">No courses found. Add a course from Courses & batches.</div>'}</div>`);
  }
  let ens=await publicData('enrollments').catch(()=>[]);let ids=ens.map(e=>e.batch_id);let bs=ids.length?await result(sb.from('batches').select('*').in('id',ids)).catch(()=>[]):[];let cs=bs.length?await result(sb.from('courses').select('*').in('id',bs.map(b=>b.course_id))).catch(()=>[]):[];
  return shell(`<div class="page-title"><div><h1>My courses</h1><p>Your batch enrollments and access status.</p></div><a href="#courses" class="btn btn-primary">Explore courses</a></div><div class="grid">${ens.length?ens.map(e=>{let b=bs.find(x=>x.id===e.batch_id),c=cs.find(x=>x.id===b?.course_id);return `<article class="course-card"><div class="course-content"><span class="tag">${esc(e.status)}</span><h3>${esc(c?.title||'Course')}</h3><p>${esc(b?.name||'Batch')} · ${esc(b?.batch_code||'')}</p><p>Enrollment: ${date(e.enrolled_at)}<br>Expires: ${date(e.expires_at)}</p>${status(e.status)}</div></article>`}).join(''):'<div class="empty" style="grid-column:1/-1">No enrollments yet. <a href="#courses">Browse courses</a></div>'}</div>`)
}
const examNoExpiry=e=>!e.end_time||new Date(e.end_time)-Date.now()>3*365*864e5;
const examEndText=e=>examNoExpiry(e)?'No expiry':date(e.end_time);
const examWindow=e=>{if(!e.enforce_schedule)return 'open';let now=Date.now();if(e.start_time&&new Date(e.start_time)>now)return 'upcoming';if(!examNoExpiry(e)&&new Date(e.end_time)<=now)return 'closed';return 'open'};
async function myExams(){let exams=await publicData('exams').catch(()=>[]);let attempts=await publicData('exam_attempts').catch(()=>[]);return shell(`<div class="page-title"><div><h1>Examinations</h1><p>আপনার ভর্তি হওয়া কোর্সের সব পরীক্ষা প্র্যাকটিস এক্সাম — যেকোনো সময়, যতবার খুশি দিতে পারবেন।</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Examination</th><th>ধরন</th><th>প্রশ্ন সংখ্যা/নম্বর</th><th>সময়কাল</th><th>অবস্থা</th><th></th></tr></thead><tbody>${exams.length?exams.map(e=>{let a=attempts.filter(x=>x.exam_id===e.id);return `<tr><td><strong>${esc(e.title)}</strong>${e.enforce_schedule?`<br><small class="muted">শুরু: ${date(e.start_time)}${examNoExpiry(e)?'':' · শেষ: '+date(e.end_time)}</small>`:''}</td><td><span class="tag">প্র্যাকটিস এক্সাম</span>${e.is_public?' <span class="tag">পাবলিক</span>':''}</td><td>${e.total_marks} নম্বর${subjRules(e)?`<br><small class="muted">বাধ্যতামূলক + যেকোনো ${subjRules(e).pick}টি ঐচ্ছিক বিষয়</small>`:''}</td><td>${e.duration_minutes} মিনিট</td><td>${a.length?status(a.at(-1).status)+' · '+a.length+' বার':'<span class="muted">এখনো দেননি</span>'}</td><td style="white-space:nowrap"><a class="btn btn-outline btn-sm" href="#exam-info/${e.id}">Details</a> ${state.roles.includes('admin')?'':(examWindow(e)!=='open'&&!a.some(x=>x.status==='in_progress'))?`<button class="btn btn-outline btn-sm" disabled>${examWindow(e)==='upcoming'?'এখনও শুরু হয়নি':'সময় শেষ'}</button>`:`<button class="btn btn-primary btn-sm" onclick="window.startExam('${e.id}')">${a.some(x=>x.status==='in_progress')?'চালিয়ে যান':'শুরু করুন'} →</button>`}</td></tr>`}).join(''):'<tr><td colspan="6"><div class="empty">No available examinations.</div></td></tr>'}</tbody></table></div></section>`)}
async function examInfo(id){let e=await result(sb.from('exams').select('*,batches(name)').eq('id',id).maybeSingle()).catch(()=>null);if(!e)return shell('<div class="empty">Examination not found or access is unavailable.</div>');return shell(`<div class="page-title"><div><a href="#my-exams" class="muted">← Examinations</a><h1 style="margin-top:12px">${esc(e.title)}</h1><p>${esc(e.description||'')}</p></div>${status(e.status)}</div><div class="grid" style="grid-template-columns:1.2fr .8fr"><section class="panel"><h3>Instructions</h3><p style="white-space:pre-wrap;line-height:1.8;color:#66748e">${esc(e.instructions||'Read each question carefully. Your answers are saved through the secure examination service.')}</p><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><p>ধরন: <strong>প্র্যাকটিস এক্সাম</strong> ${e.enforce_schedule?`(শুরু: ${date(e.start_time)}${examNoExpiry(e)?'':' · শেষ: '+date(e.end_time)}, যতবার খুশি)`:'(যেকোনো সময়, যতবার খুশি)'}</p><p>Duration: <strong>${e.duration_minutes} minutes</strong></p>${e.mcq_duration_minutes&&e.written_duration_minutes?`<p>MCQ সময়: <strong>${e.mcq_duration_minutes} মিনিট</strong> · লিখিত সময়: <strong>${e.written_duration_minutes} মিনিট</strong><br><small class="muted">আগে MCQ অংশ; MCQ-এর সময় শেষ হলে উত্তর জমা হয়ে লক হবে, তারপর লিখিত অংশ শুরু হবে।</small></p>`:''}<p>Total marks: <strong>${e.total_marks}</strong></p>${e.include_gpa?`<p>GPA marks: <strong>(SSC GPA + HSC GPA) × ${n2(gpaMultiplier(e))}</strong> — সর্বোচ্চ ${n2(10*gpaMultiplier(e))} নম্বর, মোট নম্বরের সাথে যোগ হবে</p>`:''}${subjRuleInfoHTML(e)}</section><section class="panel"><h3>Before you begin</h3><p class="muted" style="line-height:1.7">Ensure a stable internet connection. Do not refresh or close the examination window unnecessarily. Your access and attempt are validated by the server.</p>${state.roles.includes('admin')?`<button class="btn btn-outline" style="width:100%;margin-top:18px" onclick="window.previewExam('${e.id}')">View questions (admin preview) →</button><p class="muted" style="font-size:12px">Admin preview is available regardless of the scheduled start time. It does not create an exam attempt.</p>`:`<button class="btn btn-primary" style="width:100%;margin-top:18px" onclick="window.startExam('${e.id}')">প্র্যাকটিস শুরু / পুনরায় চালু করুন →</button>`}</section></div>`)}
async function adminExamPreview(id){
  if(!state.roles.includes('admin')){toast('Admin access required.',true);return;}
  const exam=await result(sb.from('exams').select('id,title,description,total_marks,subject_rules').eq('id',id).maybeSingle());
  if(!exam)throw Error('Exam not found or you do not have permission to view it.');
  const questions=await result(sb.from('exam_questions').select('*').eq('exam_id',id).order('question_order'));
  const qids=questions.map(q=>q.id);
  const options=qids.length?await result(sb.from('exam_question_options').select('*').in('exam_question_id',qids).order('display_order')):[];
  const body=questions.length?questions.map((q,i)=>{const opts=options.filter(o=>o.exam_question_id===q.id);return `<article class="notice-card"><div class="tag">QUESTION ${i+1} · ${esc(q.question_type||'')}${q.subject_name_snapshot&&subjRules(exam)?`<span class="tag" style="margin-left:8px">${esc(q.subject_name_snapshot)}</span>`:''}</div><h3>${esc(q.question_text_snapshot||'')}</h3><p class="muted">Marks: ${esc(q.marks??'—')} · Negative: ${esc(q.negative_marks??0)}</p>${opts.length?`<ol>${opts.map(o=>`<li style="margin:8px 0;${o.is_correct?'font-weight:800;color:var(--success,#16834a)':''}">${esc(o.option_label||'')}. ${esc(o.option_text||'')}${o.is_correct?' ✓ Correct answer':''}</li>`).join('')}</ol>`:''}${q.correct_answer_text_snapshot?`<p><strong>Answer:</strong> ${esc(q.correct_answer_text_snapshot)}</p>`:''}${q.explanation_snapshot?`<p><strong>Explanation:</strong> ${esc(q.explanation_snapshot)}</p>`:''}</article>`}).join(''):'<div class="empty">No questions have been added to this exam yet.</div>';
  $('#app').innerHTML=shell(`<div class="page-title"><div><a href="#exam-info/${id}" class="muted">← Back to exam</a><h1>${esc(exam.title)} — Question preview</h1><p>Admin-only preview. Schedule restrictions do not apply; no student attempt is started.</p></div></div><section class="panel"><div class="panel-head"><h3>${questions.length} questions · ${esc(exam.total_marks??'—')} total marks</h3></div>${subjRuleInfoHTML(exam)}${body}</section>`,'my-exams');translateUI();
}
async function startExam(id){try{
  let ex=await result(sb.from('exams').select('*').eq('id',id).maybeSingle()).catch(()=>null),chosen=null;
  if(subjRules(ex)){   // compulsory / optional subjects: ask which optional subjects, unless an attempt is already running
    let running=await result(sb.from('exam_attempts').select('id').eq('exam_id',id).eq('status','in_progress').limit(1)).catch(()=>[]);
    if(!running.length){chosen=await askSubjectChoice(ex);if(!chosen)return}
  }
  state.exam=ex;
  let r=await rpc('start_exam',chosen?{p_exam_id:id,p_selected_subject_ids:chosen}:{p_exam_id:id});let data=Array.isArray(r)?r[0]:r;if(data?.error)throw Error(data.error);let attemptId=data?.attempt_id||data?.id||data?.p_attempt_id;if(!attemptId)throw Error(data?.message||'The server did not return an attempt ID.');state.attempt={id:attemptId,...data};await loadExamPayload(attemptId);await initExamGpa(attemptId);state.page='exam-run';renderExam();}catch(e){err(e)}}
async function loadExamPayload(attemptId){let loaded=await rpc('load_exam_questions',{p_attempt_id:attemptId});let payload=Array.isArray(loaded)?loaded[0]:loaded;state.questions=payload.questions||payload.exam_questions||[];if(!state.questions.length&&Array.isArray(payload))state.questions=payload;state.answers={};(payload.answers||[]).forEach(a=>state.answers[a.exam_question_id]={selected_option_id:a.selected_option_id,written_answer_text:a.written_answer_text,answer_image_path:a.answer_image_path});state.questions.forEach(q=>{if(q.saved_answer)state.answers[q.id]={...(state.answers[q.id]||{}),selected_option_id:q.saved_answer.selected_option_id,written_answer_text:q.saved_answer.written_answer_text,answer_image_path:q.saved_answer.answer_image_path}});await Promise.all(Object.values(state.answers).map(async a=>{if(a?.answer_image_path)a.answer_image_url=await getAnswerSignedUrl(a.answer_image_path)}));state.qIndex=0;state.phase=payload.current_phase||'all';state.attemptTotal=payload.total_marks??null;state.selectedSubjectIds=payload.selected_subject_ids||[];const skew=payload.server_time?new Date(payload.server_time)-Date.now():0;const target=(state.phase==='mcq'&&payload.mcq_expires_at)?payload.mcq_expires_at:(payload.expires_at||state.attempt?.expires_at||Date.now()+3600000);state.remaining=Math.max(0,Math.floor((new Date(target)-(Date.now()+skew))/1000));return payload}
async function lockMcqPhase(auto=false){if(state.phaseBusy)return;if(!auto&&!confirm('MCQ অংশ জমা দেবেন? জমা দেওয়ার পর MCQ উত্তর আর পরিবর্তন করা যাবে না, এবং লিখিত অংশের সময় শুরু হবে।'))return;state.phaseBusy=true;clearInterval(timerInterval);try{if(!auto)await saveCurrent();await rpc('lock_mcq_phase',{p_attempt_id:state.attempt.id});await loadExamPayload(state.attempt.id);renderExam();window.scrollTo({top:0});toast(auto?'MCQ-এর সময় শেষ। উত্তর জমা হয়েছে, এবার লিখিত অংশ শুরু হলো।':'MCQ জমা হয়েছে। এবার লিখিত অংশ শুরু হলো।')}catch(e){if(/expired/i.test(String(e?.message||e))){state.phaseBusy=false;return submitExam(true)}err(e);tickTimer()}finally{state.phaseBusy=false}}
function examQuestionCard(q,i){
  let opts=q.options||q.exam_question_options||[];
  const saved=state.answers[q.id]||{};
  const body=opts.length?opts.map(o=>`<label class="option ${saved.selected_option_id===o.id?'selected':''}"><input type="radio" name="answer-${q.id}" value="${o.id}" ${saved.selected_option_id===o.id?'checked':''}><span><strong>${esc(o.option_label||'')}</strong> ${esc(o.option_text||'')}</span></label>`).join(''):`<div class="field"><label>Your written answer</label><textarea class="written-answer" placeholder="Write your answer here…">${esc(saved.written_answer_text||'')}</textarea></div><div class="answer-upload"><label>Upload answer image/PDF (max 15 MB)<br><input class="answer-file" type="file" accept="image/*,application/pdf"><br><button type="button" class="btn btn-outline btn-sm answer-camera-button" style="margin-top:8px">Take photo with camera</button><input class="answer-camera-file" type="file" accept="image/*" capture="environment" style="display:none"><div class="answer-upload-status" role="status" aria-live="polite" style="margin-top:8px;font-size:13px"></div><div class="answer-file-preview">${answerFilePanelMarkup(saved.answer_image_path,saved.answer_image_url)}</div></label><small>Private answer-script storage</small></div>`;
  return `<section class="panel question-card" id="qcard-${i}" data-qid="${q.id}"><div class="question-number">QUESTION ${i+1} OF ${state.questions.length} · ${esc(q.question_type||'mcq').toUpperCase()}${subjTag(q)}</div><div class="question-text">${esc(q.question_text_snapshot||q.question_text||'')}</div>${body}</section>`;
}
function isAnswered(q){let a=state.answers[q.id];return !!(a&&(a.selected_option_id||(a.written_answer_text||'').trim()||a.answer_image_path))}
function refreshPalette(){state.questions.forEach((x,i)=>{$$(`[data-q="${i}"]`).forEach(b=>b.classList.toggle('done',isAnswered(x)))});let n=state.questions.filter(isAnswered).length;$$('.exam-progress').forEach(e=>e.textContent=`${n}/${state.questions.length} answered`)}
function phaseBanner(){if(state.phase==='mcq')return '<div class="panel" style="border-left:4px solid var(--primary,#4f7cff)"><strong>ধাপ ১: MCQ অংশ</strong><p class="muted" style="margin:6px 0 0">এই অংশের নিজস্ব সময় আছে। সময় শেষ হলে (অথবা আপনি জমা দিলে) MCQ উত্তর স্বয়ংক্রিয়ভাবে জমা হবে এবং আর বদলানো যাবে না। তারপর লিখিত প্রশ্ন দেখানো হবে।</p></div>';if(state.phase==='written')return '<div class="panel" style="border-left:4px solid var(--success,#16834a)"><strong>ধাপ ২: লিখিত অংশ</strong><p class="muted" style="margin:6px 0 0">MCQ অংশ জমা হয়ে গেছে। এখন লিখিত অংশের সময় চলছে।</p></div>';return ''}
async function initExamGpa(attemptId){state.gpa=null;if(!state.exam?.include_gpa)return;let att=await result(sb.from('exam_attempts').select('ssc_gpa,hsc_gpa').eq('id',attemptId).maybeSingle()).catch(()=>null);const ssc=att?.ssc_gpa??state.profile?.ssc_gpa??null,hsc=att?.hsc_gpa??state.profile?.hsc_gpa??null;state.gpa={ssc,hsc};if(ssc!=null&&hsc!=null&&(att?.ssc_gpa==null||att?.hsc_gpa==null))await rpc('set_attempt_gpa',{p_attempt_id:attemptId,p_ssc:ssc,p_hsc:hsc}).catch(()=>{})}
function gpaPanel(){if(!state.exam?.include_gpa||!state.gpa)return '';const m=gpaMultiplier(state.exam);return `<section class="panel question-card" id="gpa-panel"><div class="tag">GPA</div><div class="question-text">আপনার SSC ও HSC GPA দিন <small class="muted">(GPA marks = (SSC + HSC) × ${n2(m)}, মোট নম্বরের সাথে যোগ হবে)</small></div><div class="form-grid"><div class="field"><label>GPA 1 — SSC GPA</label><input id="gpa-ssc" type="number" step="0.01" min="0" max="5" inputmode="decimal" value="${state.gpa.ssc??''}" placeholder="e.g. 5.00"></div><div class="field"><label>GPA 2 — HSC GPA</label><input id="gpa-hsc" type="number" step="0.01" min="0" max="5" inputmode="decimal" value="${state.gpa.hsc??''}" placeholder="e.g. 5.00"></div></div><small class="muted gpa-status"></small></section>`}
function gpaValid(){return !state.exam?.include_gpa||(state.gpa&&state.gpa.ssc!=null&&state.gpa.hsc!=null)}
async function pushGpa(){if(!state.exam?.include_gpa||!state.gpa)return true;const ssc=parseGpa($('#gpa-ssc')?.value??state.gpa.ssc),hsc=parseGpa($('#gpa-hsc')?.value??state.gpa.hsc);state.gpa={ssc,hsc};if(ssc==null||hsc==null)return false;try{await rpc('set_attempt_gpa',{p_attempt_id:state.attempt.id,p_ssc:ssc,p_hsc:hsc});state.profile={...state.profile,ssc_gpa:ssc,hsc_gpa:hsc};const st=$('.gpa-status');if(st)st.textContent='Saved ✓';return true}catch(e){err(e);return false}}
function wireGpaPanel(){['#gpa-ssc','#gpa-hsc'].forEach(sel=>{const el=$(sel);if(el)el.addEventListener('change',()=>{const ok=pushGpa();const st=$('.gpa-status');if(st&&!parseGpa(el.value))st.textContent='GPA must be between 0 and 5.'})})}
function renderExam(){
  if(!state.questions||!state.questions.length){toast('No examination questions were returned.',true);go('my-exams');return}
  const dark=(document.documentElement.dataset.theme||localStorage.getItem('admirank-theme')||'dark')==='dark';
  $('#app').innerHTML=`<div class="app-shell exam-single"><main class="main-area"><header class="exam-topbar"><strong class="exam-title">${esc(state.exam?.title||'Examination in progress')}</strong><div class="exam-top-right"><span class="exam-progress muted"></span><div class="timer exam-timer" id="timer" title="Time remaining">--:--</div><button class="theme-toggle" data-theme-toggle type="button">${dark?'☀ লাইট মোড':'☾ ডার্ক মোড'}</button><button class="btn btn-danger btn-sm" id="submit-exam">${state.phase==='mcq'?'MCQ জমা দিন':'Submit'}</button></div></header><div class="dash-content"><div class="exam-layout"><div class="exam-questions">${subjectBanner()}${phaseBanner()}${gpaPanel()}${state.questions.map(examQuestionCard).join('')}<div class="panel" style="text-align:center"><p class="muted">${state.phase==='mcq'?'MCQ অংশ শেষ। উত্তর দেখে নিয়ে প্রস্তুত হলে জমা দিন — এরপর আর MCQ উত্তর বদলানো যাবে না।':'You have reached the end. Review your answers, then submit when ready.'}</p><button class="btn btn-danger" id="submit-exam-bottom">${state.phase==='mcq'?'MCQ জমা দিন ও লিখিত অংশে যান':'Submit examination'}</button></div></div><aside class="exam-side"><section class="panel"><div class="muted" style="text-align:center;font-weight:700">QUESTIONS</div><div class="question-palette" style="margin-top:12px">${state.questions.map((x,i)=>`<button type="button" class="qdot ${isAnswered(x)?'done':''}" data-q="${i}">${i+1}</button>`).join('')}</div><p class="muted" style="font-size:11px;margin-top:14px">Green indicates an answered question. Click a number to jump to it.</p></section></aside></div></div></main></div>`;
  translateUI();
  $$('[data-theme-toggle]').forEach(b=>b.onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
  state.questions.forEach((q,i)=>{
    const card=$('#qcard-'+i);if(!card)return;
    $$('input[type=radio]',card).forEach(el=>el.addEventListener('change',async()=>{state.answers[q.id]={...(state.answers[q.id]||{}),selected_option_id:el.value};$$('.option',card).forEach(o=>o.classList.toggle('selected',$('input',o).checked));refreshPalette();await saveAnswer(q)}));
    const ta=$('.written-answer',card);
    if(ta){ta.addEventListener('input',()=>{state.answers[q.id]={...(state.answers[q.id]||{}),written_answer_text:ta.value};refreshPalette()});ta.addEventListener('blur',async()=>{state.answers[q.id]={...(state.answers[q.id]||{}),written_answer_text:ta.value};await saveAnswer(q)})}
    const g=$('.answer-file',card),c=$('.answer-camera-file',card),cb=$('.answer-camera-button',card);
    if(g)g.addEventListener('change',async e=>{await uploadAnswer(q,e.target.files?.[0]);e.target.value='';refreshPalette()});
    if(cb&&c)cb.addEventListener('click',()=>c.click());
    if(c)c.addEventListener('change',async e=>{await uploadAnswer(q,e.target.files?.[0]);e.target.value='';refreshPalette()});
  });
  $$('[data-q]').forEach(b=>b.onclick=()=>{$('#qcard-'+b.dataset.q)?.scrollIntoView({behavior:'smooth',block:'start'})});
  {const h=state.phase==='mcq'?(()=>lockMcqPhase(false)):(()=>submitExam());$('#submit-exam').onclick=h;$('#submit-exam-bottom').onclick=h}
  wireGpaPanel();refreshPalette();tickTimer();
}

async function saveAnswer(q){try{let a=state.answers[q.id]||{};await rpc('save_exam_answer',{p_attempt_id:state.attempt.id,p_exam_question_id:q.id,p_selected_option_id:a.selected_option_id||null,p_written_answer_text:a.written_answer_text||null,p_answer_image_path:a.answer_image_path||null});return true}catch(e){err(e);return false}}
async function saveCurrent(){for(const q of state.questions){let card=$$('.question-card').find(c=>c.dataset.qid===q.id),ta=card&&$('.written-answer',card);if(ta)state.answers[q.id]={...(state.answers[q.id]||{}),written_answer_text:ta.value};if(ta||state.answers[q.id]){const ok=await saveAnswer(q);if(!ok)throw Error('Your answers could not be saved. Please check your connection and retry before submitting.')}}return true}
function setAnswerUploadStatus(message,isError=false,q){
  const card=q&&$$('.question-card').find(c=>c.dataset.qid===q.id);
  const el=card?$('.answer-upload-status',card):$('.answer-upload-status');
  if(el){el.textContent=message;el.style.color=isError?'#dc2626':'var(--success,#16834a)'}
}
async function getAnswerSignedUrl(path){
  if(!path)return null;
  try{
    const {data,error}=await sb.storage.from('answer-scripts').createSignedUrl(path,3600);
    if(error)throw error;
    return data?.signedUrl||null;
  }catch(e){
    console.warn('Could not create a signed answer-file URL:',e);
    return null;
  }
}
function answerMediaMarkup(path,url,compact=false){
  if(!path)return '';
  if(!url)return '<small class="muted">The file path is saved, but its private preview could not be opened.</small>';
  const isPdf=/\.pdf$/i.test(String(path).split('?')[0]);
  if(isPdf)return `<a class="btn btn-outline btn-sm" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open uploaded PDF ↗</a>`;
  const width=compact?'120px':'100%';
  const height=compact?'110px':'420px';
  return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" title="Open uploaded answer image"><img src="${esc(url)}" alt="Uploaded answer script" loading="lazy" style="display:block;max-width:${width};max-height:${height};width:auto;height:auto;object-fit:contain;border:1px solid var(--line);border-radius:10px;margin-top:8px"></a>`;
}
function answerFilePanelMarkup(path,url){
  if(!path)return '';
  const filename=String(path).split('/').pop();
  return `<div class="notice-card" style="margin-top:10px;padding:12px"><strong>Answer file saved</strong><div class="muted" style="font-size:12px;margin-top:4px">${esc(filename)}</div>${answerMediaMarkup(path,url,true)}<small class="muted" style="display:block;margin-top:7px">You can choose another file or take another photo to replace this answer.</small></div>`;
}
async function prepareAnswerFile(file){
  if(!file)throw Error('No file was selected.');
  if(file.size>15*1024*1024)throw Error('File exceeds 15 MB. Choose a smaller image or PDF.');
  let type=(file.type||'').toLowerCase();
  const ext=(file.name||'').split('.').pop().toLowerCase();
  const extTypes={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',pdf:'application/pdf',heic:'image/heic',heif:'image/heif',avif:'image/avif'};
  if(!type||type==='application/octet-stream')type=extTypes[ext]||type;
  if(type==='application/pdf'){
    if(file.size>15*1024*1024)throw Error('PDF exceeds 15 MB.');
    return {file,type:'application/pdf',extension:'pdf'};
  }
  if(['image/jpeg','image/png','image/webp'].includes(type)){
    const extension=type==='image/jpeg'?'jpg':type.split('/')[1];
    return {file,type,extension};
  }
  if(type.startsWith('image/')){
    // Mobile devices may return HEIC/HEIF/AVIF. Convert when this browser can decode it.
    try{
      if(!window.createImageBitmap)throw Error('Image conversion is not supported by this browser.');
      const bitmap=await createImageBitmap(file);
      const canvas=document.createElement('canvas');
      canvas.width=bitmap.width;canvas.height=bitmap.height;
      const ctx=canvas.getContext('2d');
      if(!ctx)throw Error('Could not process this image.');
      ctx.drawImage(bitmap,0,0);bitmap.close?.();
      const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.88));
      if(!blob)throw Error('Could not convert this photo to JPG.');
      const converted=new File([blob],`${(file.name||'answer').replace(/\.[^.]+$/,'')}.jpg`,{type:'image/jpeg',lastModified:Date.now()});
      return {file:converted,type:'image/jpeg',extension:'jpg'};
    }catch(e){
      throw Error('This phone selected a HEIC/HEIF or unsupported image. Please change the camera format to JPG, or save/export the photo as JPG and upload it again.');
    }
  }
  throw Error('Unsupported file. Please choose a JPG, PNG, WebP image or PDF.');
}
async function uploadAnswer(q,file){
  if(!file)return;
  const card=$$('.question-card').find(c=>c.dataset.qid===q.id),input=$('.answer-file',card),cameraInput=$('.answer-camera-file',card);
  if(input)input.disabled=true;if(cameraInput)cameraInput.disabled=true;
  setAnswerUploadStatus('Preparing your answer file…',false,q);
  try{
    const prepared=await prepareAnswerFile(file);
    const uid=state.user?.id,attemptId=state.attempt?.id;
    if(!uid||!attemptId)throw Error('Your exam session could not be verified. Your exam has not been submitted. Please stay on this page and contact the administrator.');
    // Storage policy requires: <auth.uid()>/<attempt_id>/<filename>
    const safeName=(prepared.file.name||`answer.${prepared.extension}`).replace(/[^a-zA-Z0-9._-]/g,'_');
    const path=`${uid}/${attemptId}/${Date.now()}-${safeName}`;
    setAnswerUploadStatus('Uploading… please keep this exam page open.',false,q);
    const up=await sb.storage.from('answer-scripts').upload(path,prepared.file,{
      upsert:false,contentType:prepared.type,cacheControl:'3600'
    });
    if(up.error)throw up.error;
    const signedUrl=await getAnswerSignedUrl(path);
    state.answers[q.id]={...(state.answers[q.id]||{}),answer_image_path:path,answer_image_url:signedUrl};
    const saved=await saveAnswer(q);
    if(saved===false)throw Error('The file reached Storage, but its answer record was not saved. The file is not yet attached to your submitted answer. Please retry or contact the administrator.');
    const preview=$('.answer-file-preview',card);
    if(preview)preview.innerHTML=answerFilePanelMarkup(path,signedUrl);
    setAnswerUploadStatus('Answer file uploaded and linked to this question successfully.',false,q);
    toast('Answer file uploaded and saved.');
  }catch(e){
    console.error('Answer upload failed:',e);
    setAnswerUploadStatus(e?.message||'Upload failed. Your exam is still open.',true,q);
    toast(e?.message||'Answer upload failed. Your exam is still open.',true);
  }finally{
    if(input)input.disabled=false;if(cameraInput)cameraInput.disabled=false;
  }
}
let timerInterval;
function tickTimer(){clearInterval(timerInterval);const update=()=>{let t=state.remaining;let el=$('#timer');if(!el)return;el.textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;if(t<=0){clearInterval(timerInterval);state.phase==='mcq'?lockMcqPhase(true):submitExam(true)}else state.remaining--};update();timerInterval=setInterval(update,1000)}
async function submitExam(auto=false){if(!auto&&state.exam?.include_gpa){const ssc=parseGpa($('#gpa-ssc')?.value),hsc=parseGpa($('#gpa-hsc')?.value);if(ssc==null||hsc==null){toast('Please enter your SSC GPA and HSC GPA (0–5) before submitting.',true);$('#gpa-panel')?.scrollIntoView({behavior:'smooth',block:'start'});return}state.gpa={ssc,hsc}}if(!auto&&!confirm('Submit this examination? You may not be able to change your answers afterward.'))return;try{if(!auto)await pushGpa();await saveCurrent();await rpc('submit_exam_attempt',{p_attempt_id:state.attempt.id});clearInterval(timerInterval);statusModal({icon:'✓',tone:'success',title:auto?'সময় শেষ — উত্তরপত্র জমা হয়েছে':'উত্তরপত্র সফলভাবে জমা হয়েছে',message:'আপনার উত্তরপত্র আমাদের কাছে পৌঁছেছে। ফলাফল পরবর্তী দিনে প্রকাশ করা হবে।',steps:['ফলাফল প্রকাশিত হলে "ফলাফল" পেজে দেখতে পাবেন','এই পরীক্ষার উত্তর আর পরিবর্তন করা যাবে না'],button:'ফলাফল পেজে যান',onClose:()=>go('results')})}catch(e){err(e)}}
async function resultsPage(){let rs=await publicData('exam_results').catch(()=>[]);let ats=await publicData('exam_attempts').catch(()=>[]);let exams=rs.length?await result(sb.from('exams').select('*').in('id',rs.map(x=>x.exam_id))).catch(()=>[]):[];const anyGpa=exams.some(e=>e.include_gpa);return shell(`<div class="page-title"><div><h1>My results</h1><p>Published results and examination performance.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Examination</th><th>MCQ</th><th>Written</th>${anyGpa?'<th>GPA</th>':''}<th>Total</th><th>Rank</th><th>Evaluated</th><th></th></tr></thead><tbody>${rs.length?rs.map(r=>`<tr><td><strong>${esc(exams.find(e=>e.id===r.exam_id)?.title||'Examination')}</strong></td><td>${r.mcq_marks??'—'}</td><td>${r.written_marks??'—'}</td>${anyGpa?`<td>${exams.find(e=>e.id===r.exam_id)?.include_gpa?(r.gpa_marks??0):'—'}</td>`:''}<td><strong>${r.total_marks}</strong>${(a=>a?.total_marks!=null?` <small class="muted">/ ${n2(Number(a.total_marks)+(exams.find(e=>e.id===r.exam_id)?.include_gpa?10*gpaMultiplier(exams.find(e=>e.id===r.exam_id)):0))}</small>`:'')(ats.find(x=>x.id===r.attempt_id))}</td><td>${r.rank_position??'—'}</td><td>${date(r.evaluated_at)}</td><td><a class="btn btn-outline btn-sm" href="#result/${r.attempt_id}">Review</a></td></tr>`).join(''):'<tr><td colspan="7"><div class="empty">No published results yet.</div></td></tr>'}</tbody></table></div></section>`)}
async function resultDetail(id){
  let r=await result(sb.from('exam_results').select('*').eq('attempt_id',id).maybeSingle()).catch(()=>null);
  let a=await result(sb.from('exam_attempts').select('*').eq('id',id).maybeSingle()).catch(()=>null);
  let e=r?await result(sb.from('exams').select('*').eq('id',r.exam_id).maybeSingle()).catch(()=>null):null;
  let answers=a?await result(sb.from('student_answers').select('*').eq('attempt_id',id)).catch(()=>[]):[];
  let pub=r?await result(sb.from('exam_result_publications').select('*').eq('exam_id',r.exam_id).maybeSingle()).catch(()=>null):null;
  let detail=[];
  if(answers.length){let ids=answers.map(x=>x.exam_question_id);detail=await result(sb.from('exam_questions').select('id,question_text_snapshot,question_type,correct_answer_text_snapshot,explanation_snapshot').in('id',ids)).catch(()=>[])}
  const baseOut=a?.total_marks??e?.total_marks??null,outOf=baseOut!=null&&e?.include_gpa?n2(Number(baseOut)+10*gpaMultiplier(e)):baseOut;
  let subjBreak='';
  if(r&&a&&subjRules(e)){   // subject-wise marks for compulsory/optional exams (only the subjects this student sat)
    const allQ=await result(sb.from('exam_questions').select('id,subject_name_snapshot,marks').eq('exam_id',r.exam_id)).catch(()=>[]);
    const inA=new Set(Array.isArray(a.question_order)?a.question_order:[]),got={},by={};
    answers.forEach(x=>{got[x.exam_question_id]=Number(x.obtained_marks||0)});
    allQ.filter(q=>inA.has(q.id)).forEach(q=>{const k=q.subject_name_snapshot||'—';by[k]=by[k]||{got:0,out:0};by[k].out+=Number(q.marks||0);by[k].got+=got[q.id]||0});
    const ks=Object.keys(by);
    if(ks.length)subjBreak=`<section class="panel"><h3>বিষয়ভিত্তিক নম্বর</h3><div class="table-wrap"><table><thead><tr><th>বিষয়</th><th>প্রাপ্ত নম্বর</th><th>পূর্ণমান</th></tr></thead><tbody>${ks.map(k=>`<tr><td><strong>${esc(k)}</strong></td><td>${n2(by[k].got)}</td><td>${n2(by[k].out)}</td></tr>`).join('')}</tbody></table></div></section>`;
  }
  const mediaUrls={};
  await Promise.all(answers.filter(x=>x.answer_image_path).map(async x=>{mediaUrls[x.id]=await getAnswerSignedUrl(x.answer_image_path)}));
  return shell(`<div class="page-title"><div><a href="#results" class="muted">← Results</a><h1 style="margin-top:12px">${esc(e?.title||'Result details')}</h1></div></div>${r?`<div class="stat-grid"><div class="stat-card"><div class="stat-label">Total marks</div><strong>${r.total_marks}${outOf!=null?` <small class="muted">/ ${outOf}</small>`:''}</strong></div><div class="stat-card"><div class="stat-label">MCQ marks</div><strong>${r.mcq_marks}</strong></div><div class="stat-card"><div class="stat-label">Written marks</div><strong>${r.written_marks}</strong></div>${e?.include_gpa?`<div class="stat-card"><div class="stat-label">GPA marks</div><strong>${r.gpa_marks??0}</strong>${a?.ssc_gpa!=null&&a?.hsc_gpa!=null?` <small class="muted">SSC ${a.ssc_gpa} + HSC ${a.hsc_gpa}</small>`:''}</div>`:''}<div class="stat-card"><div class="stat-label">Rank</div><strong>${r.rank_position??'—'}</strong></div></div>`:''}${subjBreak}<section class="panel"><h3>Submitted answers</h3>${answers.length?answers.map(ans=>{let q=detail.find(x=>x.id===ans.exam_question_id);return `<div class="notice-card"><strong>${esc(q?.question_text_snapshot||'Question')}</strong><p>Your written answer: ${esc(ans.written_answer_text||(ans.selected_option_id?'MCQ option submitted':(ans.answer_image_path?'Image/PDF submitted':'Not answered')))}</p>${answerMediaMarkup(ans.answer_image_path,mediaUrls[ans.id])}<p>Marks: ${ans.obtained_marks??'Pending'} · ${status(ans.evaluation_status||'pending')}</p>${pub?.show_correct_answers?`<p>Correct answer: ${esc(q?.correct_answer_text_snapshot||'See correct option')}</p><p>${esc(q?.explanation_snapshot||'')}</p>`:''}</div>`}).join(''):'<div class="empty">No answer details available.</div>'}</section>`)
}

