/* ===== Compulsory / optional subjects (v13) ===== */
const subjRules=e=>{const r=e&&e.subject_rules;return r&&Array.isArray(r.subjects)&&Number(r.pick)>0&&r.subjects.some(s=>s.kind==='optional')?r:null};
const n2=v=>Math.round(Number(v||0)*100)/100;
const subjMaxTotal=(subs,pick)=>n2(subs.filter(s=>s.kind!=='optional').reduce((a,s)=>a+Number(s.marks||0),0)+subs.filter(s=>s.kind==='optional').map(s=>Number(s.marks||0)).sort((a,b)=>b-a).slice(0,pick).reduce((a,b)=>a+b,0));
const subjNames=(subs,kind)=>subs.filter(s=>(kind==='optional')===(s.kind==='optional')).map(s=>esc(s.name)).join(', ');
const subjTag=q=>subjRules(state.exam)&&q.subject_name?`<span class="tag" style="margin-left:8px">${esc(q.subject_name)}</span>`:'';
function subjRuleInfoHTML(e){const r=subjRules(e);if(!r)return '';return `<div class="notice-card" style="margin:14px 0"><strong>বিষয় নির্বাচন</strong><p style="margin:8px 0 0">বাধ্যতামূলক বিষয়: <strong>${subjNames(r.subjects,'compulsory')||'—'}</strong></p><p style="margin:6px 0 0">ঐচ্ছিক বিষয় (যেকোনো ${r.pick}টি বাছাই করতে হবে): <strong>${subjNames(r.subjects,'optional')}</strong></p><small class="muted">পরীক্ষা শুরুর সময় আপনি ঐচ্ছিক বিষয় বেছে নেবেন। শুধু বাধ্যতামূলক ও আপনার বাছাই করা বিষয়ের প্রশ্ন আসবে এবং নম্বর সেই অনুযায়ী গণনা হবে।</small></div>`}
const subjRuleShort=e=>{const r=subjRules(e);return r?`<small>${subjNames(r.subjects,'compulsory')||'—'} + যেকোনো ${r.pick}টি: ${subjNames(r.subjects,'optional')}</small>`:'<span class="muted">—</span>'};
function subjectBanner(){const r=subjRules(state.exam);if(!r)return '';const ids=new Set(state.selectedSubjectIds||[]);const chosen=r.subjects.filter(s=>s.kind==='optional'&&ids.has(s.id)).map(s=>esc(s.name)).join(', ');return `<div class="panel" style="border-left:4px solid var(--primary,#4f7cff)"><strong>আপনার বিষয়সমূহ</strong><p class="muted" style="margin:6px 0 0">বাধ্যতামূলক: ${subjNames(r.subjects,'compulsory')||'—'} · ঐচ্ছিক (আপনার বাছাই): ${chosen||'—'}${state.attemptTotal!=null?` · মোট নম্বর: ${esc(state.attemptTotal)}`:''}</p></div>`}
/* Student picks the optional subjects before a NEW attempt starts. Resolves to an array of subject ids, or null if cancelled. */
function askSubjectChoice(exam){
  const r=subjRules(exam),comp=r.subjects.filter(s=>s.kind!=='optional'),opt=r.subjects.filter(s=>s.kind==='optional'),pick=Number(r.pick),compMarks=comp.reduce((a,s)=>a+Number(s.marks||0),0);
  return new Promise(resolve=>{
    const host=document.createElement('div');
    host.innerHTML=`<div class="modal-backdrop" id="subj-modal"><div class="modal"><h2>ঐচ্ছিক বিষয় বাছাই করুন</h2><p class="muted">${esc(exam.title||'')}</p>
<div class="notice-card"><strong>বাধ্যতামূলক বিষয়</strong><p style="margin:6px 0 0">${comp.length?comp.map(s=>`${esc(s.name)} <small class="muted">(${s.marks} নম্বর)</small>`).join(' · '):'—'}</p></div>
<p style="margin:16px 0 8px"><strong>ঐচ্ছিক বিষয় — যেকোনো ${pick}টি বেছে নিন</strong></p>
<div id="subj-opts">${opt.map(s=>`<label class="option"><input type="checkbox" value="${s.id}"><span><strong>${esc(s.name)}</strong> <small class="muted">· ${s.marks} নম্বর</small></span></label>`).join('')}</div>
<p id="subj-sum" class="muted" style="margin:12px 0 0"></p>
<p class="muted" style="font-size:12px;margin:8px 0 0">এই চেষ্টা শুরু করার পর বিষয় বদলানো যাবে না। শুধু বাধ্যতামূলক ও আপনার বাছাই করা বিষয়ের প্রশ্ন আসবে এবং নম্বর সেই অনুযায়ী গণনা হবে।</p>
<div class="modal-actions"><button type="button" class="btn btn-outline" id="subj-cancel">বাতিল</button><button type="button" class="btn btn-primary" id="subj-go" disabled>পরীক্ষা শুরু করুন</button></div></div></div>`;
    const m=host.firstElementChild;document.body.appendChild(m);
    const boxes=[...m.querySelectorAll('#subj-opts input')],go=m.querySelector('#subj-go'),sum=m.querySelector('#subj-sum');
    const done=v=>{m.remove();resolve(v)};
    const refresh=()=>{const on=boxes.filter(b=>b.checked),n=on.length;boxes.forEach(b=>{b.disabled=!b.checked&&n>=pick;b.closest('.option').classList.toggle('selected',b.checked)});const marks=compMarks+on.reduce((a,b)=>a+Number(opt.find(s=>s.id===b.value)?.marks||0),0);sum.textContent=`বাছাই করা হয়েছে ${n}/${pick} · মোট নম্বর: ${n2(marks)}`;go.disabled=n!==pick};
    boxes.forEach(b=>b.addEventListener('change',refresh));refresh();
    m.querySelector('#subj-cancel').onclick=()=>done(null);
    go.onclick=()=>done(boxes.filter(b=>b.checked).map(b=>b.value));
  });
}
function qbSubjectGroups(rows){const order=Object.fromEntries(qbTax.subjects.map(s=>[s.id,s.display_order])),m=new Map();rows.forEach(q=>{if(!q.subject_id)return;const g=m.get(q.subject_id)||{id:q.subject_id,name:qbSubject(q.subject_id)?.name||'Subject',count:0,marks:0};g.count++;g.marks+=Number(q.marks||0);m.set(q.subject_id,g)});return [...m.values()].sort((a,b)=>(order[a.id]??0)-(order[b.id]??0))}
/* Reads the subject-rule part of the "Make exam" form. Returns null when the option is off, else {rules,total}. */
function qbBuildSubjectRules(rows,fd){
  if(fd.get('subj_rule')!=='on')return null;
  const groups=qbSubjectGroups(rows).map(g=>({...g,kind:fd.get('subj_kind_'+g.id)==='optional'?'optional':'compulsory'})),opt=groups.filter(g=>g.kind==='optional'),pick=Math.floor(Number(fd.get('subj_pick'))||0);
  if(opt.length<2)throw Error('Mark at least two subjects as Optional, or turn off compulsory / optional subjects.');
  if(pick<1||pick>=opt.length)throw Error(`Students must choose between 1 and ${opt.length-1} optional subject(s).`);
  const noSubject=rows.filter(q=>!q.subject_id).reduce((a,q)=>a+Number(q.marks||0),0);
  return {rules:{pick,subjects:groups.map(({id,name,kind,marks,count})=>({id,name,kind,marks:n2(marks),count}))},total:n2(noSubject+subjMaxTotal(groups,pick))};
}
