const qbSourceOptions=(selected,withNew)=>`<option value="">— No source —</option>`+qbTax.sources.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')+(withNew?`<option value="__new__">＋ Add new source…</option>`:'');
async function qbAddSource(name){name=String(name||'').replace(/\s+/g,' ').trim();if(!name)throw Error('Type a source name.');let have=qbTax.sources.find(s=>s.name.trim().toLowerCase()===name.toLowerCase());if(have)return have;let order=qbTax.sources.reduce((m,s)=>Math.max(m,s.display_order||0),0)+1;let row=await result(sb.from('qb_sources').insert({name,display_order:order}).select('*').single());qbTax.sources.push(row);return row}
function qbWireSourceField(f){let sel=f.elements.source_id,box=f.elements.new_source;if(!sel||!box)return;const sync=()=>{let add=sel.value==='__new__';box.style.display=add?'':'none';box.required=add;if(add)box.focus()};sel.onchange=sync;sync()}
async function qbResolveSource(f,fd){let v=fd.get('source_id')||'';if(v==='__new__')return await qbAddSource(fd.get('new_source'));return v?qbSource(v)||null:null}

async function questionBankPage(){
  await qbLoadTax().catch(e=>{throw /migration-v10/.test(e?.message||'')?e:Error('The question bank tables are missing. Run supabase-migration-v9-question-bank.sql in the Supabase SQL Editor first.')});
  const p=qbParams(),fc=p.get('course')||'',fs=p.get('subject')||'',ft=p.get('type')||'',fu=p.get('used')||'',fsrc=p.get('source')||'',fq=(p.get('q')||'').trim().replace(/[%_]/g,' '),pick=p.get('pick')==='1';
  const build=()=>{let q=sb.from('qb_questions').select('*').order('created_at',{ascending:false});if(fc)q=q.eq('course_id',fc);if(fs)q=q.eq('subject_id',fs);if(ft)q=q.eq('question_type',ft);if(fsrc==='none')q=q.is('source_id',null);else if(fsrc)q=q.eq('source_id',fsrc);if(fq)q=q.ilike('question_text','%'+fq+'%');return q};
  const [all,uses,exams]=await Promise.all([qbFetchAll(build),qbFetchAll(()=>sb.from('exam_questions').select('id,bank_question_id,exam_id').not('bank_question_id','is',null)).catch(()=>[]),publicData('exams','id,title').catch(()=>[])]);
  const examTitle=Object.fromEntries(exams.map(e=>[e.id,e.title]));
  const usedBy={};for(const u of uses){(usedBy[u.bank_question_id]??=new Set()).add(u.exam_id)}
  let rows=all.filter(q=>fu==='used'?usedBy[q.id]:fu==='unused'?!usedBy[q.id]:true);
  qbRows.clear();rows.forEach(q=>qbRows.set(q.id,q));
  const LIMIT=500,shown=rows.slice(0,LIMIT);
  const mcqN=rows.filter(q=>q.question_type==='mcq').length;
  const sel=(name,val,opts)=>`<select name="${name}" class="qb-filter">${opts}</select>`;
  const courseOpts=`<option value="">All courses</option>`+qbTax.courses.map(c=>`<option value="${c.id}" ${c.id===fc?'selected':''}>${esc(c.name)}</option>`).join('');
  const subjectOpts=`<option value="">All subjects</option>`+qbSubjectOptions(fc,fs);
  const typeOpts=`<option value="">MCQ + Written</option><option value="mcq" ${ft==='mcq'?'selected':''}>MCQ only</option><option value="written" ${ft==='written'?'selected':''}>Written only</option>`;
  const usedOpts=`<option value="">Used + unused</option><option value="unused" ${fu==='unused'?'selected':''}>Not used in any exam</option><option value="used" ${fu==='used'?'selected':''}>Already used in an exam</option>`;
  const sourceOpts=`<option value="">All sources</option><option value="none" ${fsrc==='none'?'selected':''}>No source</option>`+qbTax.sources.map(s=>`<option value="${s.id}" ${s.id===fsrc?'selected':''}>${esc(s.name)}</option>`).join('');
  const tags=q=>usedBy[q.id]?[...usedBy[q.id]].map(id=>`<span class="tag qb-used" title="${esc(examTitle[id]||'Exam')}">${esc(qbShort(examTitle[id]||'Exam'))}</span>`).join(' '):'<span class="muted">Unused</span>';
  const body=shown.length?shown.map((q,i)=>`<tr><td><input type="checkbox" data-qb-sel="${q.id}" ${qbSel.has(q.id)?'checked':''} aria-label="Select question"></td><td>${i+1}</td><td class="qb-text"><div>${esc(mathCut(q.question_text,110))}</div><small class="muted">${esc(mathCut(q.explanation,80))}</small></td><td>${esc(qbCourse(q.course_id)?.name||'—')}<br><small class="muted">${esc(qbSubject(q.subject_id)?.name||'—')}</small></td><td class="qb-source">${q.source_id?`<span title="${esc(qbSourceName(q.source_id))}">${esc(qbSourceName(q.source_id)||'—')}</span>`:'<span class="muted">—</span>'}</td><td><span class="tag">${q.question_type==='mcq'?'MCQ':'Written'}</span></td><td>${esc(qbCorrectText(q).slice(0,45))}</td><td>${esc(q.marks)}${q.question_type==='mcq'&&Number(q.negative_marks)?` <small class="muted">(−${esc(q.negative_marks)})</small>`:''}</td><td class="qb-tags">${tags(q)}</td><td style="white-space:nowrap"><button class="btn btn-outline btn-sm" data-qb-edit="${q.id}">Edit</button> <button class="btn btn-danger btn-sm" data-qb-del="${q.id}">Delete</button></td></tr>`).join(''):`<tr><td colspan="10"><div class="empty">No questions found. Use “Add question” or “Bulk upload”.</div></td></tr>`;
  return shell(`<div class="page-title"><div><h1>Question bank</h1><p>Upload every question once with its answer and short solution, then pick questions to build exams.</p></div><div class="toolbar"><button class="btn btn-primary" id="qb-add">＋ Add question</button><button class="btn btn-outline" id="qb-bulk">⇪ Bulk upload (Excel)</button><button class="btn btn-outline" id="qb-sources">Manage sources</button></div></div>
${pick?`<div class="notice-card qb-pick"><strong>Create an exam from the bank</strong><p class="muted">Filter by course, subject or type, tick the questions you want (selection is kept while you change filters), then press “Make exam from selected”.</p></div>`:''}
<form class="panel qb-filters" id="qb-filter-form"><div class="toolbar">${sel('course','',courseOpts)}${sel('subject','',subjectOpts)}${sel('type','',typeOpts)}${sel('source','',sourceOpts)}${sel('used','',usedOpts)}<input class="search-input" name="q" value="${esc(p.get('q')||'')}" placeholder="Search question text…"><button class="btn btn-outline btn-sm" type="submit">Search</button><a class="btn btn-outline btn-sm" href="#admin-questions${pick?'?pick=1':''}">Reset</a></div></form>
<section class="panel"><div class="panel-head"><h3>Questions</h3><span class="muted">${rows.length} found · ${mcqN} MCQ · ${rows.length-mcqN} written${rows.length>LIMIT?` · showing first ${LIMIT} — narrow the filters`:''}</span></div><div class="table-wrap"><table class="qb-table"><thead><tr><th><input type="checkbox" id="qb-sel-all" aria-label="Select all shown"></th><th>#</th><th>Question / short solution</th><th>Course · Subject</th><th>Source</th><th>Type</th><th>Answer</th><th>Marks</th><th>Used in</th><th>Actions</th></tr></thead><tbody>${body}</tbody></table></div></section>
<div class="qb-bar" id="qb-bar" ${qbSel.size?'':'hidden'}><span><strong id="qb-count">${qbSel.size}</strong> selected</span><button class="btn btn-outline btn-sm" id="qb-clear">Clear</button><button class="btn btn-primary" id="qb-make">Make exam from selected →</button></div>`,'admin-questions')}

function qbUpdateBar(){let bar=$('#qb-bar');if(!bar)return;bar.hidden=!qbSel.size;let c=$('#qb-count');if(c)c.textContent=qbSel.size}
function wireQuestionBank(){
  const form=$('#qb-filter-form');
  if(form){const apply=()=>{let fd=new FormData(form),sp=new URLSearchParams();for(const [k,v] of fd)if(String(v).trim())sp.set(k,String(v).trim());if(qbParams().get('pick')==='1')sp.set('pick','1');go('admin-questions'+(sp.toString()?'?'+sp:''))};
    form.onsubmit=e=>{e.preventDefault();apply()};
    $$('.qb-filter',form).forEach(s=>s.onchange=()=>{if(s.name==='course'){let sub=form.elements.subject;if(sub)sub.value=''}apply()})}
  $$('[data-qb-sel]').forEach(c=>c.onchange=()=>{c.checked?qbSel.add(c.dataset.qbSel):qbSel.delete(c.dataset.qbSel);qbUpdateBar()});
  $('#qb-sel-all')?.addEventListener('change',e=>{$$('[data-qb-sel]').forEach(c=>{c.checked=e.target.checked;e.target.checked?qbSel.add(c.dataset.qbSel):qbSel.delete(c.dataset.qbSel)});qbUpdateBar()});
  $('#qb-clear')?.addEventListener('click',()=>{qbSel.clear();$$('[data-qb-sel]').forEach(c=>c.checked=false);qbUpdateBar()});
  $('#qb-add')?.addEventListener('click',()=>showQbForm(null));
  $('#qb-bulk')?.addEventListener('click',showQbBulk);
  $('#qb-sources')?.addEventListener('click',()=>showQbSources().catch(err));
  $('#qb-make')?.addEventListener('click',async()=>{try{await showQbMakeExam()}catch(x){err(x)}});
  $$('[data-qb-edit]').forEach(b=>b.onclick=()=>showQbForm(qbRows.get(b.dataset.qbEdit)));
  $$('[data-qb-del]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this question from the bank? Exams that already use it keep their own copy.'))return;try{let {error}=await sb.from('qb_questions').delete().eq('id',b.dataset.qbDel);if(error)throw error;qbSel.delete(b.dataset.qbDel);toast('Question deleted.');render()}catch(x){err(x)}})
}

/* ---- add / edit one question ---- */
function showQbForm(row){
  const p=qbParams(),defCourse=row?.course_id||p.get('course')||qbTax.courses[0]?.id,defSubject=row?.subject_id||p.get('subject')||'';
  const defSource=row?(row.source_id||''):(qbSource(qbLastSource)?qbLastSource:(qbSource(p.get('source'))?p.get('source'):''));
  const opt=l=>`<div class="field"><label>Option ${l}</label><input name="option_${l.toLowerCase()}" value="${esc(row?.['option_'+l.toLowerCase()]||'')}"></div>`;
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="qb-modal"><form class="modal exam-create-modal" id="qb-form"><h2>${row?'Edit question':'Add question to bank'}</h2>
<div class="form-grid"><div class="field"><label>Course</label><select name="course_id" required>${qbTax.courses.map(c=>`<option value="${c.id}" ${c.id===defCourse?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>
<div class="field"><label>Subject</label><select name="subject_id" required></select></div>
<div class="field"><label>Question type</label><select name="question_type"><option value="mcq" ${row?.question_type!=='written'?'selected':''}>MCQ</option><option value="written" ${row?.question_type==='written'?'selected':''}>Written</option></select></div>
<div class="field"><label>Marks</label><input name="marks" type="number" step="any" min="0" value="${esc(row?.marks??1)}"></div></div>
<div class="field"><label>Source</label><select name="source_id">${qbSourceOptions(defSource,true)}</select><input name="new_source" placeholder="New source name, e.g. Udvash DU A QB Model Test - 02" style="display:none;margin-top:8px"></div>
<div class="field"><label>Question</label><textarea name="question_text" required rows="3">${esc(row?.question_text||'')}</textarea></div>
<div id="qb-mcq-box"><div class="form-grid">${['A','B','C','D'].map(opt).join('')}</div><div class="form-grid"><div class="field"><label>Correct option</label><select name="correct_option">${['A','B','C','D'].map(l=>`<option ${row?.correct_option===l?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Negative marks</label><input name="negative_marks" type="number" step="any" min="0" value="${esc(row?.negative_marks??0)}"></div></div></div>
<div class="field" id="qb-written-box"><label>Answer</label><textarea name="answer_text" rows="3">${esc(row?.answer_text||'')}</textarea></div>
<div class="field"><label>Short solution</label><textarea name="explanation" required rows="3" placeholder="A few lines explaining how to reach the answer">${esc(row?.explanation||'')}</textarea></div>
<div class="field qb-preview-box" id="qb-preview-box" hidden><label>Maths preview</label><div class="qb-preview" id="qb-preview"></div></div>
<p class="muted" style="font-size:12px;margin:0 0 12px">Maths: write LaTeX between dollar signs, e.g. <code>$\\frac{3}{4}$</code>, <code>$x^{2}$</code>, <code>$\\sqrt{x}$</code>.</p>
<div class="modal-actions"><button type="button" class="btn btn-outline" id="qb-cancel">Cancel</button>${row?'':'<button class="btn btn-outline" data-again="1">Save & add another</button>'}<button class="btn btn-primary">${row?'Save changes':'Save question'}</button></div></form></div>`);
  const f=$('#qb-form'),sync=()=>{let mcq=f.elements.question_type.value==='mcq';$('#qb-mcq-box').style.display=mcq?'':'none';$('#qb-written-box').style.display=mcq?'none':'';f.elements.answer_text.required=!mcq};
  const fill=sel=>{f.elements.subject_id.innerHTML=qbSubjectOptions(f.elements.course_id.value,sel)};
  fill(defSubject);sync();translateUI(f);qbWireSourceField(f);
  const prev=()=>{let v=k=>f.elements[k]?.value||'',mcq=f.elements.question_type.value==='mcq',parts=[v('question_text')];if(mcq)for(let l of 'abcd'){if(v('option_'+l).trim())parts.push(l.toUpperCase()+'. '+v('option_'+l))}else if(v('answer_text').trim())parts.push(v('answer_text'));parts.push(v('explanation'));
    let all=parts.join('\n'),has=/\$|\\\(|\\\[/.test(all),box=$('#qb-preview-box');box.hidden=!has;if(has){$('#qb-preview').innerHTML=parts.filter(x=>x.trim()).map(x=>`<div>${esc(x)}</div>`).join('');window.admirankRenderMath?.($('#qb-preview'))}};
  f.addEventListener('input',prev);f.elements.question_type.addEventListener('change',prev);prev();
  f.elements.course_id.onchange=()=>fill('');f.elements.question_type.onchange=sync;$('#qb-cancel').onclick=()=>$('#qb-modal').remove();
  f.onsubmit=async e=>{e.preventDefault();let again=e.submitter?.dataset.again==='1',fd=new FormData(f),mcq=fd.get('question_type')==='mcq',t=k=>String(fd.get(k)||'').trim();
    try{let o={course_id:fd.get('course_id'),subject_id:fd.get('subject_id'),question_type:fd.get('question_type'),question_text:t('question_text'),explanation:t('explanation'),marks:Number(fd.get('marks')||1),negative_marks:mcq?Number(fd.get('negative_marks')||0):0};
      if(!o.subject_id)throw Error('Select a subject.');if(!o.question_text)throw Error('Write the question.');if(!o.explanation)throw Error('Add a short solution.');
      if(mcq){for(let l of ['a','b','c','d'])o['option_'+l]=t('option_'+l)||null;o.correct_option=t('correct_option');o.answer_text=t('answer_text')||null;if(!o.option_a||!o.option_b)throw Error('An MCQ needs at least options A and B.');if(!o['option_'+o.correct_option.toLowerCase()])throw Error(`Option ${o.correct_option} is marked correct but is empty.`)}
      else{Object.assign(o,{option_a:null,option_b:null,option_c:null,option_d:null,correct_option:null,answer_text:t('answer_text')});if(!o.answer_text)throw Error('Write the answer for this written question.')}
      let srcRow=await qbResolveSource(f,fd);o.source_id=srcRow?srcRow.id:null;qbLastSource=o.source_id||'';
      let res=row?await sb.from('qb_questions').update(o).eq('id',row.id):await sb.from('qb_questions').insert(o);if(res.error)throw res.error;
      toast(row?'Question updated.':'Question saved to the bank.');
      if(again){for(let k of ['question_text','explanation','answer_text','option_a','option_b','option_c','option_d']){if(f.elements[k])f.elements[k].value=''}if(f.elements.source_id){f.elements.source_id.innerHTML=qbSourceOptions(o.source_id||'',true);f.elements.new_source.value='';qbWireSourceField(f)}f.elements.question_text.focus();render()}
      else{$('#qb-modal').remove();render()}}
    catch(x){err(x)}}
}

/* ---- Excel bulk upload ---- */
function downloadQuestionTemplate(){if(!window.XLSX){toast('Excel library is still loading. Refresh and try again.',true);return}
  let SRC=qbTax.sources[0]?.name||'';
  let rows=[['subject','question_type','question_text','option_a','option_b','option_c','option_d','correct_option','answer_text','explanation','marks','negative_marks','source'],
  ['Math','mcq','What is the value of $\\frac{1}{2}+\\frac{1}{4}$?','$\\frac{1}{4}$','$\\frac{3}{4}$','$\\frac{2}{6}$','$1$','B','','$\\frac{1}{2}+\\frac{1}{4}=\\frac{2}{4}+\\frac{1}{4}=\\frac{3}{4}$',1,0.25,SRC],
  ['Physics','written',"Explain Newton's first law.",'','','','','',"An object stays at rest or in uniform motion unless acted on by a net external force.",'Inertia: no net force means no change in motion.',5,0,SRC]];
  let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),'Questions');XLSX.writeFile(wb,'AdmiRank-Question-Bank-Template.xlsx')}
function showQbBulk(){
  const p=qbParams(),defCourse=p.get('course')||qbTax.courses[0]?.id;
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="qb-modal"><form class="modal exam-create-modal" id="qb-bulk-form"><h2>Bulk upload questions</h2><p class="muted">Every row needs its answer and a short solution. MCQ rows need options and a correct option (A–D); written rows need <code>answer_text</code>. The <code>subject</code> column is optional — if empty, the default subject below is used. The optional <code>source</code> column (it must match an existing source name) overrides the source chosen below for that row. Maths: write fractions and formulas in LaTeX between dollar signs, e.g. <code>$\\frac{3}{4}$</code>.</p>
<div class="form-grid"><div class="field"><label>Course</label><select name="course_id" required>${qbTax.courses.map(c=>`<option value="${c.id}" ${c.id===defCourse?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Default subject</label><select name="subject_id"></select></div></div>
<div class="field"><label>Source (applied to every row without its own source)</label><select name="source_id">${qbSourceOptions(qbSource(qbLastSource)?qbLastSource:'',true)}</select><input name="new_source" placeholder="New source name" style="display:none;margin-top:8px"></div>
<div class="field"><label>Question Excel file (.xlsx)</label><input name="file" id="qb-file" type="file" accept=".xlsx,.xls,.csv" required></div>
<div class="toolbar"><button type="button" class="btn btn-outline" id="qb-template">Download Excel template</button><span id="qb-file-status" class="muted">No file selected</span></div>
<div class="modal-actions"><button type="button" class="btn btn-outline" id="qb-cancel">Cancel</button><button class="btn btn-primary" id="qb-bulk-save">Upload questions</button></div></form></div>`);
  const f=$('#qb-bulk-form'),fill=()=>{f.elements.subject_id.innerHTML=`<option value="">— none (file must have a subject column) —</option>`+qbSubjectOptions(f.elements.course_id.value,p.get('subject')||'')};
  fill();translateUI(f);qbWireSourceField(f);f.elements.course_id.onchange=fill;$('#qb-cancel').onclick=()=>$('#qb-modal').remove();$('#qb-template').onclick=downloadQuestionTemplate;$('#qb-file').onchange=e=>$('#qb-file-status').textContent=e.target.files[0]?.name||'No file selected';
  f.onsubmit=async e=>{e.preventDefault();let btn=$('#qb-bulk-save');btn.disabled=true;btn.textContent='Uploading…';try{await qbBulkUpload(f)}catch(x){err(x)}finally{if(btn.isConnected){btn.disabled=false;btn.textContent='Upload questions'}}}
}
async function qbBulkUpload(f){
  if(!window.XLSX)throw Error('Excel parser is not ready. Refresh the page and try again.');
  let fd=new FormData(f),file=fd.get('file'),courseId=fd.get('course_id'),defSubject=fd.get('subject_id'),srcChoice=fd.get('source_id')||'',newSrcName=String(fd.get('new_source')||'').trim();
  if(!file||!file.size)throw Error('Choose an Excel file.');
  if(srcChoice==='__new__'&&!newSrcName)throw Error('Type the new source name, or pick an existing source.');
  let wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),raw=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});
  let subjects=qbTax.subjects.filter(s=>s.course_id===courseId),errors=[],out=[];
  raw.forEach((r0,i)=>{
    let r={};for(let [k,v] of Object.entries(r0))r[String(k).trim().toLowerCase().replaceAll(' ','_')]=v;
    let s=k=>String(r[k]??'').trim();if(!Object.values(r).some(v=>String(v).trim()))return;
    let n=i+2,bad=m=>errors.push(`Row ${n}: ${m}`),type=(s('question_type')||'mcq').toLowerCase();
    let subj=s('subject')?subjects.find(x=>x.name.toLowerCase()===s('subject').toLowerCase()):subjects.find(x=>x.id===defSubject);
    if(!subj)return bad(s('subject')?`subject “${s('subject')}” is not in this course (valid: ${subjects.map(x=>x.name).join(', ')}).`:'no subject — fill the subject column or choose a default subject.');
    if(!['mcq','written'].includes(type))return bad(`question_type must be mcq or written (got “${type}”).`);
    let rowSrc=null,srcText=s('source')||s('source_name');if(srcText){rowSrc=qbTax.sources.find(x=>x.name.trim().toLowerCase()===srcText.toLowerCase());if(!rowSrc)return bad(`source “${srcText}” does not exist. Add it with “Manage sources” first (or fix the name).`)}
    let q={course_id:courseId,subject_id:subj.id,question_type:type,question_text:s('question_text'),explanation:s('explanation')||s('short_solution')||s('solution'),marks:s('marks')===''?1:Number(s('marks')),negative_marks:type==='mcq'&&s('negative_marks')!==''?Number(s('negative_marks')):0};
    if(!q.question_text)return bad('question_text is required.');
    if(!q.explanation)return bad('explanation (short solution) is required.');
    if(Number.isNaN(q.marks)||Number.isNaN(q.negative_marks))return bad('marks / negative_marks must be numbers.');
    if(type==='mcq'){for(let l of 'abcd')q['option_'+l]=s('option_'+l)||null;q.correct_option=s('correct_option').toUpperCase();q.answer_text=s('answer_text')||null;
      if(!q.option_a||!q.option_b)return bad('MCQ needs at least option_a and option_b.');if(!['A','B','C','D'].includes(q.correct_option)||!q['option_'+q.correct_option.toLowerCase()])return bad('correct_option must be A, B, C or D and point to a filled option.')}
    else{q.answer_text=s('answer_text');if(!q.answer_text)return bad('answer_text is required for written questions.');Object.assign(q,{option_a:null,option_b:null,option_c:null,option_d:null,correct_option:null})}
    q._src=rowSrc?rowSrc.id:null;out.push(q)});
  if(errors.length)throw Error(`Nothing was uploaded. Fix ${errors.length} problem(s): `+errors.slice(0,8).join(' • ')+(errors.length>8?` • …and ${errors.length-8} more.`:''));
  if(!out.length)throw Error('The Excel sheet has no questions.');
  let defSrc=null;if(srcChoice==='__new__')defSrc=await qbAddSource(newSrcName);else if(srcChoice)defSrc=qbSource(srcChoice)||null;
  out.forEach(q=>{q.source_id=q._src||defSrc?.id||null;delete q._src});qbLastSource=defSrc?.id||'';
  for(let i=0;i<out.length;i+=200)await result(sb.from('qb_questions').insert(out.slice(i,i+200)));
  $('#qb-modal')?.remove();toast(`${out.length} questions added to the bank${defSrc?` (source: ${defSrc.name})`:''}.`);render()
}

/* ---- manage the list of sources ---- */
async function showQbSources(){
  let counts={};
  await Promise.all([qbLoadTax(),qbFetchAll(()=>sb.from('qb_questions').select('id,source_id').order('id')).then(rows=>{for(let r of rows){let k=r.source_id||'none';counts[k]=(counts[k]||0)+1}})]);
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="qb-modal"><div class="modal exam-create-modal" id="qb-src-box"><h2>Manage sources</h2><p class="muted">A source says where a question came from (for example a model test or a book). Pick it when you add or bulk-upload questions.</p>
<form class="toolbar" id="qb-src-add" style="margin-bottom:14px"><input class="search-input" name="source_name" placeholder="New source name…" required><button class="btn btn-primary btn-sm">＋ Add source</button></form>
<div class="table-wrap"><table><thead><tr><th>Source</th><th>Questions</th><th>Actions</th></tr></thead><tbody id="qb-src-body"></tbody></table></div>
<div class="modal-actions"><button type="button" class="btn btn-outline" id="qb-cancel">Close</button></div></div></div>`);
  const box=$('#qb-src-box');
  const draw=()=>{
    $('#qb-src-body').innerHTML=(qbTax.sources.length?qbTax.sources.map(s=>`<tr><td>${esc(s.name)}</td><td>${counts[s.id]||0}</td><td style="white-space:nowrap"><button type="button" class="btn btn-outline btn-sm" data-src-rename="${s.id}">Rename</button> <button type="button" class="btn btn-danger btn-sm" data-src-del="${s.id}">Delete</button></td></tr>`).join(''):`<tr><td colspan="3"><div class="empty">No sources yet. Add one above.</div></td></tr>`)+(counts.none?`<tr><td class="muted">(no source)</td><td>${counts.none}</td><td></td></tr>`:'');
    $$('[data-src-rename]',box).forEach(b=>b.onclick=async()=>{let s=qbSource(b.dataset.srcRename),n=prompt('Rename source',s.name);if(n===null)return;n=n.replace(/\s+/g,' ').trim();if(!n||n===s.name)return;
      try{if(qbTax.sources.some(x=>x.id!==s.id&&x.name.trim().toLowerCase()===n.toLowerCase()))throw Error('Another source already has that name.');await result(sb.from('qb_sources').update({name:n}).eq('id',s.id));s.name=n;draw();toast('Source renamed.')}catch(x){err(x)}});
    $$('[data-src-del]',box).forEach(b=>b.onclick=async()=>{let s=qbSource(b.dataset.srcDel),c=counts[s.id]||0;
      if(c){toast(`“${s.name}” is used by ${c} question${c>1?'s':''}. Move those questions to another source first.`,true);return}
      if(!confirm(`Delete the source “${s.name}”?`))return;
      try{await result(sb.from('qb_sources').delete().eq('id',s.id));qbTax.sources=qbTax.sources.filter(x=>x.id!==s.id);draw();toast('Source deleted.')}catch(x){err(x)}});
    translateUI(box)};
  draw();
  $('#qb-src-add').onsubmit=async e=>{e.preventDefault();let inp=e.target.elements.source_name;
    try{let nm=inp.value.replace(/\s+/g,' ').trim();if(qbTax.sources.some(s=>s.name.trim().toLowerCase()===nm.toLowerCase()))throw Error('That source already exists.');await qbAddSource(nm);inp.value='';draw();toast('Source added.')}catch(x){err(x)}};
  $('#qb-cancel').onclick=()=>{$('#qb-modal').remove();render()};
}

/* ---- make an exam from selected bank questions ---- */
async function showQbMakeExam(){
  if(!qbSel.size)throw Error('Select at least one question first.');
  let ids=[...qbSel],rows=[];
  for(let i=0;i<ids.length;i+=80)rows.push(...await result(sb.from('qb_questions').select('*').in('id',ids.slice(i,i+80))));
  if(!rows.length)throw Error('The selected questions no longer exist.');
  const subjOrder=Object.fromEntries(qbTax.subjects.map(s=>[s.id,s.display_order])),courseOrder=Object.fromEntries(qbTax.courses.map(c=>[c.id,c.display_order]));
  rows.sort((a,b)=>(a.question_type===b.question_type?0:a.question_type==='mcq'?-1:1)||(courseOrder[a.course_id]-courseOrder[b.course_id])||(subjOrder[a.subject_id]-subjOrder[b.subject_id])||String(a.created_at).localeCompare(String(b.created_at)));
  let courses=await publicData('courses').catch(()=>[]);
  let bankCourses=[...new Set(rows.map(q=>qbCourse(q.course_id)?.name).filter(Boolean))],guess=bankCourses.length===1?courses.find(c=>String(c.title).toUpperCase().includes(bankCourses[0].toUpperCase())):null;
  let hasMcq=rows.some(q=>q.question_type==='mcq'),hasW=rows.some(q=>q.question_type!=='mcq'),total=rows.reduce((a,q)=>a+Number(q.marks||0),0);
  const pad2=n=>String(n).padStart(2,'0'),dn=new Date(),nowLocal=`${dn.getFullYear()}-${pad2(dn.getMonth()+1)}-${pad2(dn.getDate())}T${pad2(dn.getHours())}:${pad2(dn.getMinutes())}`;
  const subjGroups=qbSubjectGroups(rows);
  const subjBlock=subjGroups.length>=2?`<div class="field"><label><input type="checkbox" name="subj_rule" id="subj-rule-on" style="width:auto"> Compulsory / optional subjects (students choose some subjects)</label></div>
<div id="subj-rule-box" style="display:none;margin:0 0 14px;padding:14px;border:1px solid var(--line);border-radius:12px"><p class="muted" style="font-size:12px;margin:0 0 10px">Mark each subject as Compulsory or Optional. Every student gets all compulsory questions plus only the optional subjects they choose, and their marks are calculated on those only (e.g. DU A: Physics + Chemistry compulsory, any two of the rest).</p>
<div class="table-wrap"><table><thead><tr><th>Subject</th><th>Questions</th><th>Marks</th><th>Type</th></tr></thead><tbody>${subjGroups.map(g=>`<tr><td><strong>${esc(g.name)}</strong></td><td>${g.count}</td><td>${n2(g.marks)}</td><td><select name="subj_kind_${g.id}"><option value="compulsory" selected>Compulsory</option><option value="optional">Optional</option></select></td></tr>`).join('')}</tbody></table></div>
<div class="field" style="margin-top:12px"><label>How many optional subjects must each student choose?</label><input name="subj_pick" id="subj-pick" type="number" min="1" value="2"></div>
<p id="subj-summary" class="muted" style="font-size:13px;margin:0"></p></div>`:'';
  let host=document.createElement('div');host.innerHTML=`<div class="modal-backdrop" id="qb-modal"><form class="modal exam-create-modal" id="qb-exam-form"><h2>Make exam from ${rows.length} question${rows.length>1?'s':''}</h2><p class="muted">${rows.filter(q=>q.question_type==='mcq').length} MCQ · ${rows.filter(q=>q.question_type!=='mcq').length} written · ${total} total marks. Questions are copied into the exam, so later edits to the bank never change a published exam.</p>
<div class="field"><label>Course (students of this course can take the exam)</label><select name="course_id" required>${courses.map(c=>`<option value="${c.id}" ${c.id===guess?.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div>
<div class="field"><label>Exam title</label><input name="title" required placeholder="e.g. DU A Unit Model Test 01"></div>
<div class="field"><label>Description / instructions</label><textarea name="instructions" placeholder="Instructions for students"></textarea></div>
${subjBlock}
<div class="form-grid"><div class="field"><label>Exam opens (start time)</label><input name="start_time" type="datetime-local" value="${nowLocal}"></div><div class="field"><label>Exam ends / expires (end time — optional)</label><input name="end_time" type="datetime-local"></div></div>
<p class="muted" style="font-size:12px;margin:0 0 12px">Leave “expires” empty to keep the exam open. After the expiry time students can no longer start the exam; anyone who already started can finish within their own time limit.</p>
<div class="form-grid">${hasMcq?`<div class="field"><label>MCQ সময় (মিনিট)</label><input name="mcq_duration" type="number" min="1" value="30"></div>`:''}${hasW?`<div class="field"><label>লিখিত (Written) সময় (মিনিট)</label><input name="written_duration" type="number" min="1" value="60"></div>`:''}</div>
${hasMcq&&hasW?`<p class="muted" style="font-size:12px;margin:0 0 12px">MCQ ও লিখিত দুই ধরনের প্রশ্ন থাকায় আগে MCQ-এর সময়, শেষ হলে MCQ লক হয়ে লিখিত অংশ শুরু হবে।</p>`:''}
<div class="field"><label><input type="checkbox" name="include_gpa" style="width:auto"> Include GPA marks (SSC GPA + HSC GPA)</label><small class="muted" style="display:block;margin-top:4px">Students enter SSC and HSC GPA as the first two items. GPA marks = (SSC + HSC) × (exam total marks ÷ 50): ×1 for a 50-mark exam, ×2 for a 100-mark exam. Added on top of the exam marks.</small></div>
<div class="field"><label><input type="checkbox" name="is_public" style="width:auto"> Public exam</label><small class="muted" style="display:block;margin-top:4px">Any logged-in student can see and take this exam from the dashboard, even without enrolling in the course. Needs the exam to be published.</small></div>
<div class="field"><label><input type="checkbox" name="publish" style="width:auto"> Publish immediately</label></div>
<div class="modal-actions"><button type="button" class="btn btn-outline" id="qb-cancel">Cancel</button><button class="btn btn-primary" id="qb-exam-save">Create exam</button></div></form></div>`;
  document.body.appendChild(host.firstElementChild);let f=$('#qb-exam-form');translateUI(f);$('#qb-cancel').onclick=()=>$('#qb-modal').remove();
  {const on=$('#subj-rule-on',f);if(on){const box=$('#subj-rule-box',f),sum=$('#subj-summary',f),upd=()=>{box.style.display=on.checked?'block':'none';if(!on.checked)return;const g=subjGroups.map(x=>({...x,kind:f.elements['subj_kind_'+x.id].value})),opt=g.filter(x=>x.kind==='optional'),comp=g.filter(x=>x.kind!=='optional'),pick=Math.floor(Number(f.elements.subj_pick.value)||0),noSubj=rows.filter(q=>!q.subject_id).reduce((a,q)=>a+Number(q.marks||0),0);
    let msg=`Compulsory: ${comp.map(x=>x.name).join(', ')||'none'} · Optional: ${opt.map(x=>x.name).join(', ')||'none'} (each student chooses ${pick||'?'}).`;
    if(opt.length<2)msg+=' ⚠ Mark at least two subjects as Optional.';else if(pick<1||pick>=opt.length)msg+=` ⚠ Choose a number between 1 and ${opt.length-1}.`;else{msg+=` Each student’s total = ${subjMaxTotal(g,pick)+noSubj} marks.`;if(new Set(opt.map(x=>n2(x.marks))).size>1)msg+=' Optional subjects have different marks, so a student’s total depends on their choice; the exam total shown is the highest possible.'}
    sum.textContent=msg};on.addEventListener('change',upd);f.addEventListener('change',e=>{if(e.target.matches('[name^="subj_"]'))upd()});f.elements.subj_pick.addEventListener('input',upd);upd()}}
  f.onsubmit=async e=>{e.preventDefault();let btn=$('#qb-exam-save');btn.disabled=true;btn.textContent='Creating…';try{await createExamFromBank(rows,new FormData(f))}catch(x){err(x)}finally{if(btn.isConnected){btn.disabled=false;btn.textContent='Create exam'}}}
}
async function createExamFromBank(rows,fd){
  const sRaw=String(fd.get('start_time')||''),eRaw=String(fd.get('end_time')||'');
  let startAt=sRaw?new Date(sRaw):new Date(),endAt=eRaw?new Date(eRaw):null;
  if(isNaN(startAt))throw Error('Enter a valid opening time.');if(endAt&&isNaN(endAt))throw Error('Enter a valid expiry time.');
  if(endAt&&endAt<=new Date())throw Error('The expiry time is already in the past.');
  if(endAt&&!(endAt>startAt))throw Error('The expiry time must be after the opening time.');
  const sched=!!endAt||startAt.getTime()>Date.now()+120000;   // no schedule = always-open practice exam, as before
  let course=await result(sb.from('courses').select('*').eq('id',fd.get('course_id')).single());
  let batches=await result(sb.from('batches').select('id').eq('course_id',course.id).limit(1)).catch(()=>[]),batchId=batches[0]?.id;
  if(!batchId){let made=await result(sb.from('batches').insert({course_id:course.id,name:`${course.title} — Course Exams`,batch_code:`AUTO-${course.id.slice(0,8)}`,description:'System-managed course exam grouping.',status:'published'}).select('id').single());batchId=made.id}
  let hasMcq=rows.some(q=>q.question_type==='mcq'),hasW=rows.some(q=>q.question_type!=='mcq'),mcqMin=Math.floor(Number(fd.get('mcq_duration'))||0),wrMin=Math.floor(Number(fd.get('written_duration'))||0);
  if(hasMcq&&mcqMin<1)throw Error('MCQ অংশের সময় (মিনিট) দিন।');if(hasW&&wrMin<1)throw Error('লিখিত অংশের সময় (মিনিট) দিন।');
  let split=hasMcq&&hasW,totalMin=split?mcqMin+wrMin:(hasMcq?mcqMin:wrMin),total=rows.reduce((a,q)=>a+Number(q.marks||0),0);
  const subj=qbBuildSubjectRules(rows,fd);   // null = normal exam; else compulsory/optional subject rules (v13)
  if(subj)total=subj.total;
  let exam;try{exam=await result(sb.from('exams').insert({batch_id:batchId,title:String(fd.get('title')).trim(),description:fd.get('instructions')||null,instructions:fd.get('instructions')||null,exam_type:'mock',start_time:startAt.toISOString(),end_time:(endAt||new Date(Date.now()+10*365*864e5)).toISOString(),duration_minutes:totalMin,mcq_duration_minutes:split?mcqMin:null,written_duration_minutes:split?wrMin:null,total_marks:total,status:fd.get('publish')==='on'?'published':'draft',created_by:state.user.id,...(sched?{enforce_schedule:true}:{}),...(subj?{subject_rules:subj.rules}:{}),...(fd.get('include_gpa')==='on'?{include_gpa:true}:{}),...(fd.get('is_public')==='on'?{is_public:true}:{})}).select('id').single())}catch(x){const m=x?.message||'';throw /is_public/.test(m)?Error('Run supabase-migration-v18-public-exams.sql in the Supabase SQL Editor first, then try again.'):/include_gpa/.test(m)?Error('Run supabase-migration-v17-gpa-marks.sql in the Supabase SQL Editor first, then try again.'):/subject_rules/.test(m)?Error('Run supabase-migration-v13-subject-selection.sql in the Supabase SQL Editor first, then try again.'):/enforce_schedule/.test(m)?Error('Run supabase-migration-v12-exam-schedule.sql in the Supabase SQL Editor first, then try again.'):x}
  try{
    let eqs=await result(sb.from('exam_questions').insert(rows.map((q,i)=>({exam_id:exam.id,question_order:i+1,question_type:q.question_type,question_text_snapshot:q.question_text,correct_answer_text_snapshot:qbCorrectText(q)||null,explanation_snapshot:q.explanation||null,image_paths_snapshot:[],marks:q.marks,negative_marks:q.negative_marks,bank_question_id:q.id,...(subj?{subject_id:q.subject_id||null,subject_name_snapshot:qbSubject(q.subject_id)?.name||null}:{})}))).select('id,question_order'));
    let idByOrder=Object.fromEntries(eqs.map(x=>[x.question_order,x.id])),opts=[];
    rows.forEach((q,i)=>{if(q.question_type!=='mcq')return;['A','B','C','D'].forEach((l,k)=>{let t=qbOptionText(q,l);if(t)opts.push({exam_question_id:idByOrder[i+1],option_label:l,option_text:t,is_correct:q.correct_option===l,display_order:k+1})})});
    if(opts.length)await result(sb.from('exam_question_options').insert(opts))
  }catch(x){await sb.from('exam_questions').delete().eq('exam_id',exam.id);await sb.from('exams').delete().eq('id',exam.id);throw Error('Could not copy the questions into the exam, so nothing was created. '+(x.message||''))}
  qbSel.clear();$('#qb-modal')?.remove();toast(`Exam created with ${rows.length} questions.`);go('admin-exams')
}
async function adminCrud(route){if(route==='admin-exams')return await adminExamManager();if(route==='admin-questions')return await questionBankPage();let def=adminDefs[route];let tab=new URLSearchParams(location.hash.split('?')[1]||'').get('table');let active=def.tables.find(t=>t.table===tab)||def.tables[0];let rows=await publicData(active.table).catch(()=>[]);let displayFields=active.table==='courses'?['title','slug','price','sale_price','status']:active.fields.slice(0,5);return shell(`<div class="page-title"><div><h1>${def.title}</h1><p>Manage courses, publish or unpublish them, and create separate enrollment batches.</p></div><button class="btn btn-primary" id="add-record">＋ Add ${active.label.slice(0,-1)}</button></div><div class="toolbar" style="margin-bottom:18px">${def.tables.map(t=>`<a class="btn ${t.table===active.table?'btn-primary':'btn-outline'} btn-sm" href="#${route}?table=${t.table}">${t.label}</a>`).join('')}</div><section class="panel"><div class="panel-head"><h3>${active.label}</h3><span class="muted">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr>${displayFields.map(f=>`<th>${esc(f.replaceAll('_',' '))}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${displayFields.map(f=>`<td>${f==='status'?status(r[f]):typeof r[f]==='boolean'?status(r[f]?'active':'draft'):esc(String(r[f]??'—').slice(0,70))}</td>`).join('')}<td><button class="btn btn-outline btn-sm" data-edit="${r.id}">Edit</button> ${active.table==='courses'?`<button class="btn btn-${r.status==='published'?'outline':'primary'} btn-sm" data-course-publish="${r.id}" data-current-status="${esc(r.status||'')}">${r.status==='published'?'Unpublish':'Publish'}</button>`:''} <button class="btn btn-danger btn-sm" data-delete="${r.id}">Delete</button></td></tr>`).join(''):`<tr><td colspan="${displayFields.length+1}"><div class="empty">No ${active.label.toLowerCase()} found.</div></td></tr>`}</tbody></table></div></section>`,route)}
async function showAdminForm(table,fields,row){let courses=table==='batches'?await publicData('courses').catch(()=>[]):[];let html=`<div class="modal-backdrop" id="modal"><form class="modal" id="record-form"><h2>${row?'Edit':'Add'} ${table.replaceAll('_',' ')}</h2>${fields.map(f=>table==='batches'&&f==='course_id'?`<div class="field"><label>Course</label><select name="course_id" required><option value="">Select a course</option>${courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div>`:fieldInput(f,table)).join('')}<div class="modal-actions"><button type="button" class="btn btn-outline" id="cancel-modal">Cancel</button><button class="btn btn-primary">Save record</button></div></form></div>`;document.body.insertAdjacentHTML('beforeend',html);translateUI($('#modal'));let form=$('#record-form');if(row)for(let f of fields){let el=form.elements[f];if(el){let v=row[f];el.value=el.type==='datetime-local'&&v?new Date(v).toISOString().slice(0,16):v??''}}$('#cancel-modal').onclick=()=>$('#modal').remove();form.onsubmit=async e=>{e.preventDefault();let fd=new FormData(form),obj={};for(let f of fields){let el=form.elements[f],v=fd.get(f);if(el.tagName==='SELECT'&&['is_active','is_published','randomize_questions','randomize_options','warn_on_tab_switch','log_tab_switches','require_fullscreen','prevent_copy_paste','allow_resume','show_results','show_correct_answers'].includes(f))obj[f]=v==='true';else if(el.type==='number')obj[f]=v===''?null:Number(v);else if(el.type==='datetime-local')obj[f]=v?new Date(v).toISOString():null;else obj[f]=v===''?null:v}try{let q=sb.from(table);let res=row?await q.update(obj).eq('id',row.id):await q.insert(obj);if(res.error)throw res.error;$('#modal').remove();toast('Record saved.');render()}catch(e){err(e)}}}
async function paymentsPage(){let ps=await publicData('payments').catch(()=>[]);return shell(`<div class="page-title"><div><h1>Payment verification</h1><p>Manually verify bKash, Nagad and Rocket transactions before activating enrollments.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Amount</th><th>Method</th><th>Transaction ID</th><th>Sender phone</th><th>Submitted</th><th>Status</th><th>Action</th></tr></thead><tbody>${ps.length?ps.map(p=>`<tr><td><strong>${money(p.amount)}</strong></td><td>${esc(p.payment_method)}</td><td>${esc(p.transaction_id)}</td><td>••${esc(p.sender_phone_last2||'')}</td><td>${date(p.submitted_at)}</td><td>${status(p.status)}</td><td>${p.status==='pending'?`<button class="btn btn-primary btn-sm" data-approve="${p.id}">Approve</button> <button class="btn btn-danger btn-sm" data-reject="${p.id}">Reject</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="7"><div class="empty">No payment submissions.</div></td></tr>'}</tbody></table></div></section>`)}
async function verifyPayment(id){if(!confirm('Confirm that you verified this transaction in the actual payment provider account?'))return;try{await rpc('admin_verify_payment',{p_payment_id:id,p_transaction_id:null});toast('Payment approved and enrollment activated.');render()}catch(e){err(e)}}
async function rejectPayment(id){let reason=prompt('Enter rejection reason:');if(!reason)return;try{await rpc('admin_reject_payment',{p_payment_id:id,p_rejection_reason:reason,p_admin_note:null});toast('Payment rejected.');render()}catch(e){err(e)}}
async function adminResultsPage(){
 let [evaluations,exams,pubs]=await Promise.all([publicData('answer_evaluations').catch(()=>[]),publicData('exams').catch(()=>[]),publicData('exam_result_publications').catch(()=>[])]);
 let pending=evaluations.filter(x=>x.evaluation_status==='submitted');
 return shell(`<div class="page-title"><div><h1>Evaluation & results</h1><p>Evaluator marks are applied automatically — no approval needed. Finalize exam results, calculate ranks and publish results.</p></div></div>
 <section class="panel" ${pending.length?'':'hidden style="display:none"'}><div class="panel-head"><h3>Written evaluations awaiting approval</h3><span class="muted">${pending.length} pending</span></div>
 <div class="table-wrap"><table><thead><tr><th>Evaluation ID</th><th>Student answer</th><th>Evaluator</th><th>Marks</th><th>Feedback</th><th>Action</th></tr></thead><tbody>
 ${pending.length?pending.map(x=>`<tr><td>${esc(x.id.slice(0,8))}…</td><td>${esc(x.student_answer_id.slice(0,8))}…</td><td>${esc(x.evaluator_id.slice(0,8))}…</td><td>${x.marks_awarded}</td><td>${esc(x.feedback||'—')}</td><td><button class="btn btn-primary btn-sm" data-approve-eval="${x.id}">Approve</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">No submitted evaluations awaiting approval.</div></td></tr>'}</tbody></table></div></section>
 <section class="panel"><div class="panel-head"><h3>Exam result workflow</h3></div><div class="table-wrap"><table><thead><tr><th>Examination</th><th>Status</th><th>Publication</th><th>Actions</th></tr></thead><tbody>
 ${exams.length?exams.map(e=>{let pub=pubs.find(x=>x.exam_id===e.id);return `<tr><td><strong>${esc(e.title)}</strong></td><td>${status(e.status)}</td><td>${pub?.is_published?status('published'):'Unpublished'}</td><td><div class="toolbar"><a class="btn btn-outline btn-sm" href="#admin-exam-results/${e.id}">View all results</a><button class="btn btn-outline btn-sm" data-finalize="${e.id}">Finalize</button><button class="btn btn-outline btn-sm" data-rank="${e.id}">Calculate ranks</button><button class="btn btn-primary btn-sm" data-publish="${e.id}">Publish results</button></div></td></tr>`}).join(''):'<tr><td colspan="4"><div class="empty">No examinations found.</div></td></tr>'}</tbody></table></div><p class="muted" style="font-size:11px">Finalize only after all attempts and written evaluations are complete. The backend enforces these conditions.</p></section>`);
}
async function adminExamResultsPage(examId){let [exam,rows]=await Promise.all([result(sb.from('exams').select('*').eq('id',examId).single()),rpc('admin_exam_results_overview',{p_exam_id:examId})]);let pending=rows.filter(r=>r.written_pending>0).length,hasGpa=!!exam.include_gpa;return shell(`<div class="page-title"><div><h1>${esc(exam.title)} — all results</h1><p>Admin-only preview. Students cannot see this until you publish results.</p></div><a class="btn btn-outline" href="#admin-results">← Evaluation & results</a></div><section class="panel"><div class="panel-head"><h3>${rows.length} submitted attempt${rows.length===1?'':'s'}</h3>${pending?`<span class="muted">${pending} with unevaluated written answers</span>`:''}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Rank</th><th>Student</th><th>ID</th><th>MCQ</th><th>Written</th>${hasGpa?'<th>GPA</th>':''}<th>Total</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>#${r.rank_position}</strong></td><td><strong>${esc(r.student_name)}</strong>${r.phone?`<div class="muted" style="font-size:11px">${esc(r.phone)}</div>`:''}</td><td>${esc(r.student_code||'—')}</td><td>${r.mcq_marks}</td><td>${r.written_marks}</td>${hasGpa?`<td>${r.gpa_marks}${r.ssc_gpa!=null&&r.hsc_gpa!=null?`<div class="muted" style="font-size:11px">SSC ${r.ssc_gpa} + HSC ${r.hsc_gpa}</div>`:'<div class="muted" style="font-size:11px">GPA missing</div>'}</td>`:''}<td><strong>${r.total_marks}</strong> / ${n2(Number(r.exam_total_marks??exam.total_marks??0)+(exam.include_gpa?10*gpaMultiplier({total_marks:r.exam_total_marks??exam.total_marks}):0))}</td><td>${r.written_pending>0?`Written pending (${r.written_pending})`:r.is_finalized?'Finalized':'Evaluated, not finalized'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No submitted attempts for this exam yet.</div>'}</section>`,'admin-results')}
async function publishExamResults(examId){let currentPub=await result(sb.from('exam_result_publications').select('*').eq('exam_id',examId).maybeSingle()).catch(()=>null);let show=confirm('Show correct answers along with published results? Press OK for yes, Cancel for no.');try{let obj={exam_id:examId,is_published:true,show_correct_answers:show,published_at:new Date().toISOString(),published_by:state.user.id};let q=sb.from('exam_result_publications');let res=currentPub?await q.update(obj).eq('id',currentPub.id):await q.insert(obj);if(res.error)throw res.error;toast('Results published.');render()}catch(e){err(e)}}
async function usersPage(){
  const [candidates,assign,exams]=await Promise.all([
    rpc('admin_list_evaluator_candidates').catch(e=>{console.error('Could not load account list:',e);return []}),
    publicData('evaluator_assignments').catch(()=>[]),
    publicData('exams').catch(()=>[])
  ]);
  const candidateMap=Object.fromEntries(candidates.map(u=>[u.user_id,u]));
  const examMap=Object.fromEntries(exams.map(e=>[e.id,e]));
  const eligibleExams=exams.slice().sort((a,b)=>(a.title||'').localeCompare(b.title||''));
  const sortedCandidates=candidates.slice().sort((a,b)=>(a.full_name||a.email||'').localeCompare(b.full_name||b.email||''));
  return shell(`<div class="page-title"><div><h1>Users & evaluator assignments</h1><p>Choose an account and assign it to an examination. Evaluator access is granted automatically.</p></div></div>
  <section class="panel"><div class="panel-head"><h3>Assign an evaluator</h3><span class="tag">Admin action</span></div>
  ${!sortedCandidates.length?'<div class="empty">No user accounts were returned. Check the admin evaluator-management SQL migration and try again.</div>':!eligibleExams.length?'<div class="empty">No examinations are available to assign. Create an exam first.</div>':`<form id="assign-evaluator-form" class="form-grid">
    <div class="field"><label for="assign-evaluator-user">User account</label><select id="assign-evaluator-user" name="evaluator_id" required><option value="">Select a user</option>${sortedCandidates.map(u=>`<option value="${esc(u.user_id)}">${esc(u.full_name||u.email||u.user_id)}${u.email&&u.full_name?' · '+esc(u.email):''}${u.is_evaluator?' · Evaluator':''}</option>`).join('')}</select><small class="muted">Selecting a student account will automatically add the evaluator role.</small></div>
    <div class="field"><label for="assign-evaluator-exam">Examination</label><select id="assign-evaluator-exam" name="exam_id" required><option value="">Select an examination</option>${eligibleExams.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}${e.status==='published'?' · Published':''}</option>`).join('')}</select></div>
    <div class="field" style="grid-column:1/-1"><button class="btn btn-primary" type="submit">Assign evaluator</button></div>
  </form>`}</section>
  <section class="panel"><h3>Evaluator assignments</h3><div class="table-wrap"><table><thead><tr><th>Evaluator</th><th>Email / user ID</th><th>Examination</th><th>Assigned</th><th>Status</th></tr></thead><tbody>${assign.length?assign.map(a=>{const u=candidateMap[a.evaluator_id],e=examMap[a.exam_id];return `<tr><td><strong>${esc(u?.full_name||'Evaluator')}</strong></td><td><small>${esc(u?.email||a.evaluator_id)}</small></td><td>${esc(e?.title||a.exam_id)}</td><td>${date(a.assigned_at)}</td><td>${status(a.status)}</td></tr>`}).join(''):'<tr><td colspan="5"><div class="empty">No evaluator assignments yet. Use the form above to create the first one.</div></td></tr>'}</tbody></table></div></section>`)
}
async function evaluatorPage(){
  let as=await publicData('evaluator_assignments').catch(e=>{console.error('Could not load evaluator assignments:',e);return []});
  let ids=as.filter(a=>a.status==='active').map(a=>a.exam_id);
  let exams=ids.length?await result(sb.from('exams').select('id,title').in('id',ids)):[];
  let attempts=ids.length?await result(sb.from('exam_attempts').select('id,exam_id,student_id,status,submitted_at').in('exam_id',ids).in('status',['submitted','auto_submitted','evaluated'])):[];
  let ans=attempts.length?await result(sb.from('student_answers').select('*').in('attempt_id',attempts.map(a=>a.id))):[];
  let qs=ans.length?await result(sb.from('exam_questions').select('id,exam_id,question_text_snapshot,question_type,correct_answer_text_snapshot,marks').in('id',ans.map(a=>a.exam_question_id))):[];
  const written=ans.filter(a=>qs.some(q=>q.id===a.exam_question_id&&q.question_type==='written'));
  const mediaUrls={};
  await Promise.all(written.filter(a=>a.answer_image_path).map(async a=>{mediaUrls[a.id]=await getAnswerSignedUrl(a.answer_image_path)}));
  evalCtx={written,qs,mediaUrls};
  return shell(`<div class="page-title"><div><h1>Assigned scripts</h1><p>Review written answers for examinations assigned to you.</p></div><button class="btn btn-primary" onclick="window.evalView()">Evaluator’s view</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Examination</th><th>Question</th><th>Answer</th><th>Evaluation</th><th></th></tr></thead><tbody>${written.length?written.map(a=>{let q=qs.find(x=>x.id===a.exam_question_id),at=attempts.find(x=>x.id===a.attempt_id);return `<tr><td>${esc(exams.find(e=>e.id===at?.exam_id)?.title||'Exam')}</td><td>${esc(mathCut(q?.question_text_snapshot||'',80))}</td><td>${a.written_answer_text?`<div>${esc(a.written_answer_text.slice(0,100))}</div>`:''}${a.answer_image_path?answerMediaMarkup(a.answer_image_path,mediaUrls[a.id],true):''}${!a.written_answer_text&&!a.answer_image_path?'No response':''}</td><td>${status(a.evaluation_status||'pending')}</td><td><button class="btn btn-primary btn-sm" data-evaluate="${a.id}">Evaluate</button></td></tr>`}).join(''):'<tr><td colspan="5"><div class="empty">No assigned written scripts are available. Check that an evaluator is assigned to the exam and that students have submitted their attempts.</div></td></tr>'}</tbody></table></div></section>`)
}

/* ===== Evaluator's view: big script image (2/3 of the screen) + one-click marking ===== */
let evalCtx=null;
async function evalView(){
  const c=evalCtx;if(!c)return toast('Open the Assigned scripts page first.',true);
  const mine=await result(sb.from('answer_evaluations').select('student_answer_id,marks_awarded').eq('evaluator_id',state.user.id)).catch(()=>[]),done={};
  mine.forEach(x=>{done[x.student_answer_id]=x.marks_awarded});
  const items=c.written.filter(a=>a.answer_image_path||(a.written_answer_text||'').trim()).sort((a,b)=>String(a.exam_question_id).localeCompare(String(b.exam_question_id))||String(a.attempt_id).localeCompare(String(b.attempt_id)));
  if(!items.length)return toast('No written scripts to evaluate yet.',true);
  let i=Math.max(0,items.findIndex(a=>done[a.id]==null)),busy=false,zoom=false;
  const KEY='admirank-ev-buttons',saved=()=>(localStorage.getItem(KEY)||'').split(',').map(x=>parseFloat(x)).filter(x=>!isNaN(x)&&x>=0);
  const btnsFor=max=>{max=Number(max)||0;let v=saved();if(!v.length)v=[max,max>1?1:n2(max/2),0];v=v.filter(x=>x<=max);if(!v.includes(max))v.unshift(max);if(!v.includes(0))v.push(0);return [...new Set(v.map(n2))].sort((a,b)=>b-a)};
  const ov=document.createElement('div');ov.id='ev-overlay';ov.style.cssText='position:fixed;inset:0;z-index:9999;background:var(--bg,#0b0f17);color:var(--text,inherit);overflow:hidden';document.body.appendChild(ov);document.documentElement.style.overflow='hidden';
  const close=()=>{document.removeEventListener('keydown',key);ov.remove();document.documentElement.style.overflow='';render()};
  const nextUndone=from=>{for(let k=from+1;k<items.length;k++)if(done[items[k].id]==null)return k;return -1};
  const mark=async v=>{const a=items[i];if(busy)return;busy=true;try{const {error}=await sb.from('answer_evaluations').insert({student_answer_id:a.id,evaluator_id:state.user.id,marks_awarded:v,feedback:'',evaluation_status:'submitted'});if(error)throw error;done[a.id]=v;const n=nextUndone(i);if(n>=0)i=n;else toast('All scripts marked.')}catch(e){err(e)}finally{busy=false;draw()}};
  const go2=d=>{const n=i+d;if(n>=0&&n<items.length){i=n;draw();ov.querySelector('#ev-left')?.scrollTo(0,0)}};
  function key(e){if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape')close();else if(e.key==='ArrowRight')go2(1);else if(e.key==='ArrowLeft')go2(-1);else if(/^[1-9]$/.test(e.key)){const q=c.qs.find(x=>x.id===items[i].exam_question_id),b=btnsFor(q?.marks)[Number(e.key)-1];if(b!==undefined)mark(b)}}
  document.addEventListener('keydown',key);
  function draw(){
    const a=items[i],q=c.qs.find(x=>x.id===a.exam_question_id)||{},url=c.mediaUrls[a.id],isPdf=/\.pdf($|\?)/i.test(a.answer_image_path||''),d=done[a.id],left=ov.querySelector('#ev-left')?.scrollTop||0;
    const media=a.answer_image_path?(url?(isPdf?`<iframe src="${esc(url)}" style="width:100%;height:calc(100vh - 24px);border:0;background:#fff"></iframe>`:`<img src="${esc(url)}" alt="Answer script" style="display:block;width:${zoom?'180%':'100%'};max-width:none;height:auto;cursor:zoom-${zoom?'out':'in'}" id="ev-img">`):'<p class="muted">Could not load the file.</p>'):'';
    ov.innerHTML=`<style>#ev-wrap{display:grid;grid-template-columns:2fr 1fr;height:100%}#ev-left{overflow:auto;padding:12px;background:#10141c}#ev-right{overflow:auto;padding:18px;border-left:1px solid var(--line,#2a3142)}.ev-mark{font-size:22px;font-weight:800;padding:16px 8px;min-width:84px}@media(max-width:800px){#ev-wrap{grid-template-columns:1fr;grid-template-rows:60% 40%}#ev-right{border-left:0;border-top:1px solid var(--line,#2a3142)}}</style>
<div id="ev-wrap"><div id="ev-left">${a.written_answer_text?`<div class="notice-card" style="white-space:pre-wrap">${esc(a.written_answer_text)}</div>`:''}${media}${!media&&!a.written_answer_text?'<p class="muted">No response.</p>':''}</div>
<div id="ev-right"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><strong>Script ${i+1} / ${items.length}</strong><button class="btn btn-outline btn-sm" id="ev-close">✕ Close</button></div>
<p class="muted" style="font-size:12px;margin:6px 0 14px">${Object.keys(done).length?`${items.filter(x=>done[x.id]!=null).length} marked · ${items.filter(x=>done[x.id]==null).length} left`:`${items.length} left`}</p>
<div class="notice-card"><strong>Question</strong><div style="white-space:pre-wrap;margin-top:6px">${esc(q.question_text_snapshot||'—')}</div>${q.correct_answer_text_snapshot?`<p class="muted" style="margin:10px 0 0"><strong>Model answer:</strong> ${esc(q.correct_answer_text_snapshot)}</p>`:''}</div>
<p style="margin:16px 0 8px"><strong>Marks</strong> <span class="muted">(out of ${q.marks??'?'})</span></p>
${d!=null?`<div class="notice-card"><strong>Marked: ${d}</strong><p class="muted" style="margin:6px 0 0;font-size:12px">Saved. To change it, click another mark below.</p></div>`:''}<div style="display:flex;flex-wrap:wrap;gap:10px">${btnsFor(q.marks).map((b,k)=>`<button class="btn ${k===0?'btn-primary':'btn-outline'} ev-mark" data-v="${b}" ${busy?'disabled':''}>${b}<br><small style="font-weight:400;font-size:11px">key ${k+1}</small></button>`).join('')}</div><p class="muted" style="font-size:12px;margin-top:12px">One click saves the mark (no approval needed) and opens the next script. Wrong click? Open it again with ← and click the right mark.</p>
<div style="display:flex;gap:8px;margin-top:18px"><button class="btn btn-outline" id="ev-prev" ${i===0?'disabled':''}>← Previous</button><button class="btn btn-outline" id="ev-next" ${i===items.length-1?'disabled':''}>Next →</button>${a.answer_image_path&&!isPdf?`<button class="btn btn-outline" id="ev-zoom">${zoom?'Fit width':'Zoom in'}</button>`:''}</div>
<div class="field" style="margin-top:18px"><label>Mark buttons (comma separated, e.g. 2.5,1,0)</label><input id="ev-cfg" value="${esc(saved().join(','))}" placeholder="auto: full, half, 0"></div></div></div>`;
    ov.querySelector('#ev-left').scrollTop=left;
    ov.querySelector('#ev-close').onclick=close;ov.querySelector('#ev-prev').onclick=()=>go2(-1);ov.querySelector('#ev-next').onclick=()=>go2(1);
    ov.querySelectorAll('.ev-mark').forEach(b=>b.onclick=()=>mark(Number(b.dataset.v)));
    const z=ov.querySelector('#ev-zoom');if(z)z.onclick=()=>{zoom=!zoom;draw()};const im=ov.querySelector('#ev-img');if(im)im.onclick=()=>{zoom=!zoom;draw()};
    ov.querySelector('#ev-cfg').onchange=e=>{localStorage.setItem(KEY,e.target.value.trim());draw()};
  }
  draw();
}
async function evaluateAnswer(id){let a=await result(sb.from('student_answers').select('*').eq('id',id).maybeSingle());if(!a)throw Error('Student answer not found or you do not have access.');let q=await result(sb.from('exam_questions').select('*').eq('id',a.exam_question_id).maybeSingle());let rubric=await result(sb.from('evaluation_rubrics').select('*').eq('exam_question_id',q.id).maybeSingle()).catch(()=>null);let mediaUrl=a.answer_image_path?await getAnswerSignedUrl(a.answer_image_path):null;showEvaluationModal(a,q,rubric,mediaUrl)}
function showEvaluationModal(a,q,r,mediaUrl){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><form class="modal" id="evaluation-form"><h2>Evaluate written answer</h2><p><strong>Question</strong><br>${esc(q.question_text_snapshot)}</p>${a.written_answer_text?`<div class="notice-card"><strong>Written response</strong><p style="white-space:pre-wrap">${esc(a.written_answer_text)}</p></div>`:''}${a.answer_image_path?`<div class="notice-card"><strong>Uploaded answer file</strong>${answerMediaMarkup(a.answer_image_path,mediaUrl)}</div>`:''}${!a.written_answer_text&&!a.answer_image_path?'<p class="muted">No written response or uploaded file was attached.</p>':''}${r?`<p class="muted">${esc(r.instructions||'')}</p>`:''}<div class="field"><label>Marks awarded (max ${q.marks})</label><input name="marks" type="number" min="0" max="${q.marks}" step="0.25" required></div><div class="field"><label>Feedback</label><textarea name="feedback"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-outline" id="cancel-modal">Cancel</button><button class="btn btn-primary">Submit evaluation</button></div></form></div>`);translateUI($('#modal'));$('#cancel-modal').onclick=()=>$('#modal').remove();$('#evaluation-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{let {error}=await sb.from('answer_evaluations').insert({student_answer_id:a.id,evaluator_id:state.user.id,marks_awarded:Number(f.get('marks')),feedback:f.get('feedback'),evaluation_status:'submitted'});if(error)throw error;$('#modal').remove();toast('Marks saved.');render()}catch(e){err(e)}}}
async function about(){return `${topbar()}<section class="section"><div class="eyebrow">About AdmiRank</div><h2>Make your preparation count.</h2><p class="section-sub" style="max-width:700px">AdmiRank is an online admission-exam preparation platform designed to bring courses, examinations, results and written-script evaluation into one place.</p><div class="feature-grid" style="margin-top:30px"><div class="feature" style="background:#fff;color:var(--ink);border:1px solid var(--line)"><h3>Structured learning</h3><p>Course and batch-based preparation.</p></div><div class="feature" style="background:#fff;color:var(--ink);border:1px solid var(--line)"><h3>Secure examinations</h3><p>Server-validated attempts and answer submissions.</p></div><div class="feature" style="background:#fff;color:var(--ink);border:1px solid var(--line)"><h3>Transparent evaluation</h3><p>MCQ auto-grading and manual written evaluation.</p></div></div></section>${footer()}`}
async function paymentPage(batchId){
  if(!state.user){go('login');return ''}
  const b=await result(sb.from('batches').select('*,courses(*)').eq('id',batchId).maybeSingle()).catch(()=>null);
  if(!b||!b.courses){toast('Batch not found.',true);go('courses');return ''}
  let en;
  try{const created=await rpc('create_course_enrollment',{p_batch_id:batchId});en=Array.isArray(created)?created[0]:created;}
  catch(e){let msg=e.message||'Enrollment could not be started.';let missing=msg.includes('create_course_enrollment')||msg.includes('Could not find the function')||msg.includes('does not exist');return shell(`<div class="page-title"><div><h1>${missing?'Enrollment setup required':'Enrollment unavailable'}</h1><p>${esc(b.courses.title)} · ${esc(b.name)}</p></div></div><section class="panel" style="max-width:700px"><p>${missing?'The secure enrollment function is missing. Ask the administrator to run supabase-migration-v3-enrollment.sql in Supabase SQL Editor.':'This batch is not currently accepting enrollment.'}</p><p class="muted">${esc(msg)}</p><a class="btn btn-outline" href="#course/${encodeURIComponent(b.courses.slug||b.courses.id)}">Back to course</a></section>`)}
  const enrollmentId=typeof en==='string'?en:(en?.id||en?.create_course_enrollment);
  if(!enrollmentId)throw Error('Supabase did not return an enrollment ID.');
  const enrollment=await result(sb.from('enrollments').select('id,status').eq('id',enrollmentId).maybeSingle()).catch(()=>null);
  if(enrollment?.status==='active'){toast('You already have access to this course.');go('my-courses');return ''}
  const pendingPayment=await result(sb.from('payments').select('transaction_id,payment_method,submitted_at,status').eq('enrollment_id',enrollmentId).eq('status','pending').maybeSingle()).catch(()=>null);
  if(pendingPayment)return shell(`<div class="page-title"><div><h1>Payment under review</h1><p>${esc(b.courses.title)} · ${esc(b.name)}</p></div></div><section class="panel" style="max-width:650px"><div class="tag">PENDING ADMIN APPROVAL</div><h3>Your payment submission has been received.</h3><p>Provider: <strong>${esc(pendingPayment.payment_method)}</strong></p><p>Transaction ID: <strong>${esc(pendingPayment.transaction_id)}</strong></p><p>Submitted: ${date(pendingPayment.submitted_at)}</p><p class="muted">Your course access will be activated after an administrator verifies the transaction.</p><a class="btn btn-outline" href="#dashboard">Go to dashboard</a></section>`);
  const accounts=C.PAYMENT_ACCOUNTS||{};
  return shell(`<div class="page-title"><div><a class="muted" href="#course/${encodeURIComponent(b.courses.slug||b.courses.id)}">← Back to course</a><h1 style="margin-top:10px">Course enrollment</h1><p>${esc(b.courses.title)} · ${esc(b.name)}</p></div></div><section class="panel" style="max-width:700px"><h3>Payment details</h3><p class="price">${money(b.courses.sale_price??b.courses.price)}</p><p>1. Select your payment provider below.<br>2. Send the exact course fee to the displayed number.<br>3. Enter the Transaction ID and the last two digits of the sender's phone number.</p><form id="payment-form"><input type="hidden" name="enrollment_id" value="${esc(enrollmentId)}"><div class="field"><label>Payment method</label><select name="method" id="payment-method" required><option value="bKash">bKash</option><option value="Nagad">Nagad</option><option value="Rocket">Rocket</option></select></div><div class="notice-card" id="payment-instructions"><strong>Send money via bKash</strong><p>Account number: <strong>${esc(accounts.bKash||'Enter your bKash number in config.js')}</strong></p><small>Use Send Money and pay the exact amount shown above.</small></div><div class="field"><label>Transaction ID (TrxID)</label><input name="trx" autocomplete="off" required maxlength="100"></div><div class="field"><label>Last two digits of sender phone number</label><input name="last2" inputmode="numeric" pattern="[0-9]{2}" maxlength="2" placeholder="e.g. 42" required></div><button class="btn btn-primary" type="submit">Submit payment for approval</button></form><p class="muted">Your enrollment stays pending until an admin verifies the transaction. Never share your PIN or OTP.</p></section>`)
}

async function submitPayment(form){let f=new FormData(form);await rpc('submit_course_payment',{p_enrollment_id:f.get('enrollment_id'),p_payment_method:f.get('method'),p_transaction_id:f.get('trx'),p_sender_phone_last2:f.get('last2')});statusModal({icon:'⏳',tone:'pending',title:'এনরোলমেন্ট জমা হয়েছে',message:'আপনার পেমেন্টের তথ্য সফলভাবে জমা হয়েছে। অ্যাডমিন যাচাই করে অনুমোদন দিলে কোর্সটি আপনার জন্য চালু হবে।',steps:['অ্যাডমিন আপনার ট্রানজেকশন যাচাই করবেন','অনুমোদনের পর কোর্স ও পরীক্ষা আনলক হবে','অবস্থা দেখুন: ড্যাশবোর্ড → আমার কোর্স'],button:'ড্যাশবোর্ডে যান',onClose:()=>go('dashboard')})}
async function render(){clearInterval(timerInterval);let p=current().split('?')[0].split('/').map(routePart);state.page=p[0]||'home';try{if(['dashboard','my-courses','my-exams','results','leaderboard','profile','admin','admin-courses','admin-questions','admin-exams','admin-content','admin-payments','admin-users','admin-results','evaluator','exam-info','exam-run','admin-exam-preview','admin-exam-results','result'].includes(state.page)&&!state.user){go('login');return}let html;if(state.page==='home')html=await home();else if(state.page==='courses')html=await coursesPage();else if(state.page==='course')html=await courseDetail(p[1]);else if(state.page==='notices')html=await noticesPage();else if(state.page==='about')html=await about();else if(['login','register','forgot'].includes(state.page))html=authPage(state.page);else if(state.page==='dashboard')html=await dashboard();else if(state.page==='my-courses')html=await myCourses();else if(state.page==='my-exams')html=await myExams();else if(state.page==='exam-info')html=await examInfo(p[1]);else if(state.page==='admin-exam-preview'){if(!state.roles.includes('admin'))throw Error('Admin access required.');await adminExamPreview(p[1]);return;}else if(state.page==='admin-exam-results'){if(!state.roles.includes('admin'))throw Error('Admin access required.');html=await adminExamResultsPage(p[1])}else if(state.page==='results')html=await resultsPage();else if(state.page==='result')html=await resultDetail(p[1]);else if(state.page==='leaderboard')html=await leaderboard();else if(state.page==='profile')html=await profile();else if(state.page==='admin'){if(!state.roles.includes('admin'))throw Error('Admin access required.');html=await adminOverview()}else if(adminDefs[state.page]){if(!state.roles.includes('admin'))throw Error('Admin access required.');html=await adminCrud(state.page)}else if(state.page==='admin-payments'){if(!state.roles.includes('admin'))throw Error('Admin access required.');html=await paymentsPage()}else if(state.page==='admin-users'){if(!state.roles.includes('admin'))throw Error('Admin access required.');html=await usersPage()}else if(state.page==='admin-results'){if(!state.roles.includes('admin'))throw Error('Admin access required.');html=await adminResultsPage()}else if(state.page==='evaluator'){if(!state.roles.includes('evaluator')&&!state.roles.includes('admin'))throw Error('Evaluator access required.');html=await evaluatorPage()}else if(state.page==='payment')html=await paymentPage(p[1]);else if(state.page==='reset')html=authPage('forgot');else html=await home();$('#app').innerHTML=html;translateUI();wire();if(state.page==='dashboard')maybeAskGpa()}catch(e){err(e);$('#app').innerHTML=state.user?shell(`<div class="empty">${esc(e.message)}</div>`):`${topbar()}<div class="empty">Unable to load this page.</div>`}}
